comms.text:
@1 וּמַלִּיל יְיָ עִם משֶׁה לְמֵימָר:
@2 פַּקֵּד יָת אַהֲרֹן וְיָת בְּנוֹהִי לְמֵימָר דָּא אוֹרַיְתָא דַּעֲלָתָא הִיא עֲלָתָא עַל דְּמִתּוֹקְדָא עַל מַדְבְּחָא כָל לֵילְיָא עַד צַפְרָא וְאֶשָּׁתָא דְמַדְבְּחָא תְּהֵא יָקְדָא בֵיהּ:
@3 וְיַלְבֵּשׁ כַּהֲנָא לְבוּשִׁין דְּבוּץ וּמִכְנְסִין דְּבוּץ יַלְבֵּשׁ עַל בִּסְרֵיהּ וְיַפְרֵשׁ יָת קִטְמָא דִּי תֵיכוּל אֶשָּׁתָא יָת עֲלָתָא עַל מַדְבְּחָא וִישַׁוִּנֵּיהּ בִּסְטַר מַדְבְּחָא:
@4 וְיַשְׁלַח יָת לְבוּשׁוֹהִי וְיִלְבַּשׁ לְבוּשִׁין אָחֳרָנִין וְיַפֵּק יָת קִטְמָא לְמִבָּרָא לְמַשְׁרִיתָא לַאֲתַר דְּכֵי:
@5 וְאֶשָּׁתָא עַל מַדְבְּחָא תְהֵי יָקְדָא בֵיהּ לָא תִטְּפֵי וְיַבְעַר עֲלַהּ כַּהֲנָא אָעַיָּא בִּצְפַר בִּצְפָר וְיַסְדַּר עֲלַּהּ עֲלָתָא וְיַסֵּק עֲלַהּ תַּרְבֵּי נִכְסַת קוּדְשַׁיָּא:
@6 אֶשָּׁתָא תְּדִירָא תְּהֵי יָקְדָא עַל מַדְבְּחָא לָא תִטְּפֵי:
@7 וְדָא אוֹרַיְתָא דְּמִנְחָתָא דִּיקָרְבוּן יָתַהּ בְּנֵי אַהֲרֹן קֳדָם יְיָ לָקֳדָם מַדְבְּחָא:
@8 וְיַפְרֵשׁ מִנֵּיהּ בְּקֻמְצֵיהּ מִסֻּלְתָּא דְמִנְחָתָא וּמִמִּשְׁחַהּ וְיָת כָּל לְבוּנְתָּא דִּי עַל מִנְחָתָא וְיַסֵּק לְמַדְבְּחָא לְאִתְקַבָּלָא בְרַעֲוָא אַדְכַּרְתָּא קֳדָם יְיָ:
@9 וּדְאִשְׁתָּאַר מִנַּה יֵכְלוּן אַהֲרֹן וּבְנוֹהִי פַּטִּיר תִּתְאָכֵל בַּאֲתַר קַדִּישׁ בְּדָרַת מִשְׁכַּן זִמְנָא יֵכְלֻנַּהּ:
@10 לָא תִתְאֲפֵי חֲמִיעַ חֳלָקְהוֹן יְהָבִית יָתַהּ מִקֻּרְבָּנָי קֹדֶשׁ קוּדְשִׁין הִיא כְּחַטָּאתָא וְכַאֲשָׁמָא:
@11 כָּל דְּכוּרָא בִּבְנֵי אַהֲרֹן יֵכְלֻנַּהּ קְיָם עָלָם לְדָרָתֵיכוֹן מִקֻּרְבָּנַיָּא דַיְיָ כֹּל דְּיִקְרַב בְּהוֹן יִתְקַדָּשׁ:
@12 וּמַלִּיל יְיָ עִם משֶׁה לְמֵימָר:
@13 דֵּין קֻרְבַּן אַהֲרֹן וּבְנוֹהִי דִּי יְקָרְבוּן קֳדָם יְיָ בְּיוֹמָא דְּרַבִּיאוּ יָתֵיהּ חַד מִן עַסְרָא בִתְלַת סְאִין סֻלְתָּא מִנְחָתָא תְּדִירָא פַּלְגּוּתַהּ בְּצַפְרָא וּפַלְגּוּתַהּ בְּרַמְשָׁא:
@14 עַל מַסְרֵיתָא בִּמְשַׁח תִּתְעֲבֵד רְבִיכָא תַיְתִנַּהּ תּוּפִינֵי מִנְחַת בִּצּוּעִין תְּקָרֵב לְאִתְקַבָּלָא בְרַעֲוָא קֳדָם יְיָ:
@15 וְכַהֲנָא דִמְרַבָּא תְחוֹתוֹהִי מִבְּנוֹהִי יַעְבֵּד יָתַהּ קְיָם עָלָם קֳדָם יְיָ גְּמִיר תִּתַּסָּק:
@16 וְכָל מִנְחָתָא דְכַהֲנָא גְּמִיר תְּהֵי לָא תִתְאֲכֵל:
@17 וּמַלִּיל יְיָ עִם משֶׁה לְמֵימָר:
@18 מַלֵּל עִם אַהֲרֹן וְעִם בְּנוֹהִי לְמֵימַר דָּא אוֹרַיְתָא דְּחַטָּאתָא בְּאֲתַר דִּי תִתְנְכֵס עֲלָתָא תִּתְנְכֵס חַטָּאתָא קֳדָם יְיָ קֹדֶשׁ קוּדְשִׁין הִיא:
@19 כַּהֲנָא דִּמְכַפֵּר בִּדְמַהּ יֵיכְלִנַּהּ בַּאֲתַר קַדִּישׁ תִּתְאֲכֵל בְּדָרַת מַשְׁכַּן זִמְנָא:
@20 כֹּל דִּי יִקְרַב בְּבִסְרַהּ יִתְקַדַּשׁ וְדִי יַדִּי מִדְּמַהּ עַל לְבוּשׁ דִּי יַדִּי עֲלַהּ תִּתְחַוָּר בַּאֲתַר קַדִּישׁ:
@21 וּמָן דַּחֲסַף דִּי תִתְבַּשֵּׁל בֵּיהּ יִתָּבָר וְאִם בְּמָנָא דִּנְחָשָׁא תִּתְבַּשֵּׁל וְיִתְמְרֵק וְיִשְׁתַּטֵּף בְּמַיָּא:
@22 כָּל דְּכוּרָא בְכַהֲנַיָּא יֵכוּל יָתַהּ קֹדֶשׁ קוּדְשִׁין הִיא:
@23 וְכָל חַטָּאתָא דִּי יִתָּעַל מִדְּמַהּ לְמַשְׁכַּן זִמְנָא לְכַפָּרָא בְקוּדְשָׁא לָא תִתְאֲכֵל בְּנוּרָא תִּתּוֹקָד:
@24 וְדָא אוֹרַיְתָא דַּאֲשָׁמָא קֹדֶשׁ קוּדְשִׁין הוּא:
@25 בְאַתְרָא דִּי יִכְּסוּן יָת עֲלָתָא יִכְּסוּן יָת אֲשָׁמָא וְיָת דְּמֵיהּ יִזְרַק עַל מַדְבְּחָא סְחוֹר סְחוֹר:
@26 וְיָת כָּל תַּרְבֵּיהּ יַפְרֵשׁ מִנֵּיהּ יָת אֲלִיתָא וְיָת תַּרְבָּא דְּחָפֵי יָת גַּוָּא:
@27 וְיָת תַּרְתֵּין כָּלְיָן וְיָת תַּרְבָּא דִּי עֲלֵיהֶן דִּי עַל גִּסְסַיָּא וְיָת חִצְרָא דְּעַל כַּבְדָּא עַל כָּלְיֵתָא יֶעְדִּנַּהּ:
@28 וְיַסֵּק יָתְהוֹן כַּהֲנָא לְמַדְבְּחָא קֻרְבָּנָא קֳדָם יְיָ אֲשָׁמָא הוּא:
@29 כָּל דְּכוּרָא בְכַהֲנַיָּא יֵיכְלִנֵּיהּ בַּאֲתַר קַדִּישׁ יִתְאֲכָל קֹדֶשׁ קוּדְשִׁין הוּא:
@30 כְּחַטָּאתָא כַּאֲשָׁמָא אוֹרַיְתָא חֲדָא לְהוֹן כַּהֲנָא דִּי יְכַפֵּר בֵּיהּ דִּילֵיהּ יְהֵא:
@31 וְכַהֲנָא דִּמְקָרֵב יָת עֲלַת גְּבָר מְשַׁךְ עֲלָתָא דִּי יְקָרֵב לְכַהֲנָא דִּילֵיהּ יְהֵא:
@32 וְכָל מִנְחָתָא דִּי תִתְאֲפֵי בְּתַנּוּרָא וְכָל דְּתִתְעֲבֵד בְּרִדְתָּא וְעַל מַסְרֵיתָא לְכַהֲנָא דִּמְקָרֵב יָתַהּ דִּילֵיהּ תְּהֵא:
@33 וְכָל מִנְחָתָא דְפִילָא בִמְשַׁח וּדְלָא פִילָא לְכָל בְּנֵי אַהֲרֹן תְּהֵי גְּבַר כְּאָחוֹהִי:
@34 וְדָא אוֹרַיְתָא דְּנִכְסַת קוּדְשַׁיָּא דִּי יְקָרֵב קֳדָם יְיָ:
@35 אִם עַל תּוֹדְתָא יְקָרְבִנֵּיהּ וִיקָרֵב עַל נִכְסַת תּוֹדְתָא גְּרִיצָן פַּטִּירָן דְּפִילָן בִּמְשַׁח וְאֶסְפּוֹגִין פַּטִּירִין דִּמְשִׁיחִין בִּמְשָׁח וְסֻלְתָּא רְבִיכָא גְּרִיצָן דְּפִילָן בִּמְשָׁח:
@36 עַל גְּרִיצָן דִּלְחֵם חֲמִיעַ יְקָרֵב קֻרְבָּנֵיהּ עַל נִכְסַת תּוֹדַת קוּדְשׁוֹהִי:
@37 וִיקָרֵב מִנֵּיהּ חַד מִכָּל קוּרְבַּן אַפְרָשׁוּתָא קֳדָם יְיָ לְכַהֲנָא דִּיזְרַק יָת דַּם נִכְסַת קוּדְשַׁיָּא דִּילֵיהּ יְהֵי:
@38 וּבְסַר נִכְסַת תּוֹדַת קוּדְשׁוֹהִי בְּיוֹם קֻרְבָּנֵיהּ יִתְאֲכֵל לָא יַצְנַע מִנֵּיהּ עַד צַפְרָא:
@39 וְאִם נִדְרָא אוֹ נְדַבְתָּא נִכְסַת קֻרְבְּנֵיהּ בְּיוֹמָא דִּי יְקָרֵב יָת נִכְסְתֵיהּ יִתְאֲכֵל וּבְיוֹמָא דְבַתְרוֹהִי וּדְאִשְׁתָּאַר מִנֵּיהּ יִתְאֲכֵל:
@40 וּדְאִשְׁתָּאַר מִבְּסַר נִכְסְתָא בְּיוֹמָא תְּלִיתָאָה בְּנוּרָא יִתּוֹקָד:
@41 וְאִם אִתְאֲכָלָא יִתְאֲכֵל מִבְּסַר נִכְסַת קוּדְשׁוֹהִי בְּיוֹמָא תְלִיתָאָה לָא יְהֵא לְרַעֲוָא דִּמְקָרֵב יָתֵיהּ לָא יִתְחֲשֵׁב לֵיהּ מְרָחָק יְהֵא וֶאֱנַשׁ דְּתֵיכוּל מִנֵּיהּ חוֹבֵיהּ יְקַבֵּל:
@42 וּבְסַר קוּדְשָׁא דִּי יִקְרַב בְּכָל מְסָאָב לָא יִתְאֲכֵל בְּנוּרָא יִתּוֹקָד וּבְסַר קוּדְשָׁא כָּל דִּי דְכֵי לְקוּדְשָׁא יֵיכוּל בְּסַר קוּדְשָׁא:
@43 וֶאֱנַשׁ דִּי תֵיכוּל בִּסְרָא מִנִּכְסַת קוּדְשַׁיָּא דִּי קֳדָם יְיָ וְסוֹבְתֵיהּ עֲלוֹהִי וְיִשְׁתֵּיצֵי אֱנָשָׁא הַהִיא מֵעַמַּהּ:
@44 וֶאֱנַשׁ אֲרֵי תִקְרַב בְּכָל מְסָאָב בְּסוֹאֲבַת אֱנָשָׁא אוֹ בִּבְעִירָא מְסָאֲבָא אוֹ בְּכָל שִׁקְצָא מְסָאָב וְיֵיכוּל מִבְּסַר נִכְסַת קוּדְשַׁיָּא דִּי קֳדָם יְיָ וִישְׁתֵּיצֵי אֱנָשָׁא הַהִיא מֵעַמַּהּ:
@45 וּמַלִּיל יְיָ עִם משֶׁה לְמֵימָר:
@46 מַלֵּיל עִם בְּנֵי יִשְׂרָאֵל לְמֵימָר כָּל תְּרַב תּוֹר וְאִמָּר וְעִזָּא לָא תֵיכְלוּן:
@47 וּתְרַב נְבִילָא וּתְרַב תְּבִירָא יִתְעֲבֵד לְכָל עִבִדְתָּא וּמֵיכַל לָא תֵיכְלֻנֵּיהּ:
@48 אֲרֵי כָּל דְּיֵכוּל תַּרְבָּא מִן בְּעִירָא דִּי יְקָרְבוּן מִנַּהּ קֻרְבָּנָא קֳדָם יְיָ וְיִשְׁתֵּיצֵי אֱנָשָׁא דִי תֵיכוּל מֵעַמַּהּ:
@49 וְכָל דְּמָא לָא תֵיכְלוּן בְּכָל מוֹתְבָנֵיכוֹן דְּעוֹפָא וְדִבְעִירָא:
@50 כָּל אֱנָשָׁא דִי תֵיכוּל כָּל דְּמָא וְיִשְׁתֵּיצֵי אֱנָשָׁא הַהִיא מֵעַמַּהּ:
@51 וּמַלִּיל יְיָ עִם משֶׁה לְמֵימָר:
@52 מַלֵּיל עִם בְּנֵי יִשְׂרָאֵל לְמֵימָר דִּמְקָרֵב יָת נִכְסַת קוּדְשׁוֹהִי קֳדָם יְיָ יַיְתִי יָת קֻרְבָּנֵיהּ לָקֳדָם יְיָ מִנִּכְסַת קוּדְשׁוֹהִי:
@53 יְדוֹהִי תַיְתוּן יָת קֻרְבָּנַיָּא דַיְיָ יָת תַּרְבָּא עַל חֶדְיָא יַיְתִנֵּיהּ יָת חֶדְיָא לַאֲרָמָא יָתֵיהּ אֲרוּמָא קֳדָם יְיָ:
@54 וְיַסֵּק כַּהֲנָא יָת תַּרְבָּא לְמַדְבְּחָא וִיהֵי חֶדְיָא לְאַהֲרֹן וְלִבְנוֹהִי:
@55 וְיָת שׁוֹקָא דְיַמִּינָא תִּתְּנוּן אַפְרָשׁוּתָא לְכַהֲנָא מִנִּכְסַת קוּדְשֵׁיכוֹן:
@56 דִּמְקָרֵב יָת דַּם נִכְסַת קוּדְשַׁיָּא וְיָת תַּרְבָּא מִבְּנֵי אַהֲרֹן דִּילֵיהּ תְּהֵי שׁוֹקָא דְיַמִּינָא לָחֳלָק:
@57 אֲרֵי יָת חֶדְיָא דַאֲרָמוּתָא וְיָת שׁוֹקָא דְאַפְרָשׁוּתָא נְסֵבִית מִן בְּנֵי יִשְׂרָאֵל מִנִּכְסַת קוּדְשֵׁיהוֹן וִיהָבִית יָתְהוֹן לְאַהֲרֹן כַּהֲנָא וְלִבְנוֹהִי לִקְיָם עָלָם מִן בְּנֵי יִשְׂרָאֵל:
@58 דָּא רְבוּת אַהֲרֹן וּרְבוּת בְּנוֹהִי מִקֻּרְבָּנַיָּא דַּיְיָ בְּיוֹמָא דִּיְקָרְבוּן יָתְהוֹן לְשַׁמָּשָׁא קֳדָם יְיָ:
@59 דִּי פַּקִּיד יְיָ לְמִתַּן לְהוֹן בְּיוֹמָא דְּרַבִּי יָתְהוֹן מִן בְּנֵי יִשְׂרָאֵל קְיָם עָלָם לְדָרֵיהוֹן:
@60 דָּא אוֹרַיְתָא לַעֲלָתָא לְמִנְחָתָא וּלְחַטָּאתָא וְלַאֲשָׁמָא וּלְקֻרְבָּנַיָּא וּלְנִכְסַת קוּדְשַׁיָּא:
@61 דִּי פַקִּיד יְיָ יָת משֶׁה בְּטוּרָא דְסִינָי בְּיוֹמָא דִפַקְּדֵיהּ יָת בְּנֵי יִשְׂרָאֵל לְקָרָבָא יָת קֻרְבָּנְהוֹן קֳדָם יְיָ בְּמַדְבְּרָא דְסִינָי:
@62 וּמַלִּיל יְיָ עִם משֶׁה לְמֵימָר:
@63 קָרֵב יָת אַהֲרֹן וְיָת בְּנוֹהִי עִמֵּיהּ וְיָת לְבוּשַׁיָּא וְיָת מִשְׁחָא דִרְבוּתָא וְיָת תּוֹרָא דְחַטָּאתָא וְיָת תְּרֵין דִּכְרִין וְיָת סַלָּא דְפַטִּירַיָּא:
@64 וְיָת כָּל כְּנִשְׁתָּא כְּנֵשׁ לִתְרַע מַשְׁכַּן זִמְנָא:
@65 וַעֲבַד משֶׁה כְּמָא דִי פַּקִּיד יְיָ יָתֵיהּ וְאִתְכְּנִישַׁת כְּנִשְׁתָּא לִתְרַע מַשְׁכַּן זִמְנָא:
@66 וַאֲמַר משֶׁה לִכְנִשְׁתָּא דֵּין פִּתְגָּמָא דִּי פַקִּיד יְיָ לְמֶעְבָּד:
@67 וְקָרִיב משֶׁה יָת אַהֲרֹן וְיָת בְּנוֹהִי וְאַסְחֵי יָתְהוֹן בְּמַיָּא:
@68 וִיהַב עֲלוֹהִי יָת כִּתּוּנָא וְזָרֵז יָתֵיהּ בְּהֶמְיָנָא וְאַלְבֵּשׁ יָתֵיהּ יָת מְעִילָא וִיהַב עֲלוֹהִי יָת אֵפוֹדָא וְזָרֵז יָתֵיהּ בְּהֶמְיַן אֵפוֹדָא וְאַתְקֵן לֵיהּ בֵּיהּ:
@69 וְשַׁוִּי עֲלוֹהִי יָת חוּשְׁנָא וִיהַב בְּחוּשְׁנָא יָת אוּרַיָּא וְיָת תֻּמַיָּא:
@70 וְשַׁוִּי יָת מִצְנֶפְתָּא עַל רֵישֵׁיהּ וְשַׁוִּי עַל מִצְנֶפְתָּא לָקֳבֵל אַפּוֹהִי יָת צִיצָא דְדַהֲבָא כְּלִילָא דְקוּדְשָׁא כְּמָא דִי פַקִּיד יְיָ יָת משֶׁה:
@71 וּנְסִיב משֶׁה יָת מִשְׁחָא דִרְבוּתָא וְרַבִּי יָת מַשְׁכְּנָא וְיָת כָּל דִּי בֵיהּ וְקַדִּישׁ יָתְהוֹן:
@72 וְאַדִּי מִנֵּיהּ עַל מַדְבְּחָא שְׁבַע זִמְנִין וְרַבִּי יָת מַדְבְּחָא וְיָת כָּל מָנוֹהִי וְיָת כִּיּוֹרָא וְיָת בְּסִיסֵיהּ לְקַדָּשׁוּתְהוֹן:
@73 וַאֲרִיק מִמִּשְׁחָא דִרְבוּתָא עַל רֵישָׁא דְאַהֲרֹן וְרַבִּי יָתֵיהּ לְקַדָּשׁוּתֵיהּ:
@74 וְקָרִיב משֶׁה יָת בְּנֵי אַהֲרֹן וְאַלְבֵּשִׁנּוּן כִּתּוּנִין וְזָרֵז יָתְהוֹן הֶמְיָנִין וְאַתְקֵן לְהוֹן כּוֹבָעִין כְּמָא דִי פַקִּיד יְיָ יָת משֶׁה:
@75 וְקָרֵב יָת תּוֹרָא דְחַטָּאתָא וּסְמַךְ אַהֲרֹן וּבְנוֹהִי יָת יְדֵיהוֹן עַל רֵישׁ תּוֹרָא דְחַטָּאתָא:
@76 וּנְכֵס וּנְסִיב משֶׁה יָת דְּמָא וִיהַב עַל קַרְנַת מַדְבְּחָא סְחוֹר סְחוֹר בְּאֶצְבְּעֵיהּ וְדַכִּי יָת מַדְבְּחָא וְיָת דְּמָא אֲרִיק לִיסוֹדָא דְמַדְבְּחָא וְקַדְּשֵׁיהּ לְכַפָּרָא עֲלוֹהִי:
@77 וּנְסִיב יָת כָּל תַּרְבָּא דִּי עַל גַּוָּא וְיָת חֲצַר כַּבְדָּא וְיָת תַּרְתֵּין כָּלְיָן וְיָת תַּרְבְּהֶן וְאַסֵּק משֶׁה לְמַדְבְּחָא:
@78 וְיָת תּוֹרָא וְיָת מַשְׁכֵּיהּ וְיָת בִּסְרֵיהּ וְיָת אָכְלֵיהּ אוֹקִיד בְּנוּרָא מִבָּרָא לְמַשְׁרִיתָא כְּמָא דִי פַקִּיד יְיָ יָת משֶׁה:
@79 וְקָרִיב יָת דִּכְרָא דַעֲלָתָא וּסְמָכוּ אַהֲרֹן וּבְנוֹהִי יָת יְדֵיהוֹן עַל רֵישׁ דִּכְרָא:
@80 וּנְכֵס וּזְרַק משֶׁה יָת דְּמָא עַל מַדְבְּחָא סְחוֹר סְחוֹר:
@81 וְיָת דִּכְרָא פַּלֵּיג לְאֶבְרוֹהִי וְאַסֵּק משֶׁה יָת רֵישָׁא וְיָת אֵבָרַיָּא וְיָת תַּרְבָּא:
@82 וְיָת גַּוָּא וְיָת כְּרָעַיָּא חַלִּיל בְּמַיָּא וְאַסֵּק משֶׁה יָת כָּל דִּכְרָא לְמַדְבְּחָא עֲלָתָא הוּא לְאִתְקַבָּלָא בְרַעֲוָא קֻרְבָּנָא הוּא קֳדָם יְיָ כְּמָא דִי פַקִּיד יְיָ יָת משֶׁה:
@83 וְקָרִיב יָת דִּכְרָא תִנְיָנָא דְּכַר קֻרְבָּנַיָּא וּסְמָכוּ אַהֲרֹן וּבְנוֹהִי יָת יְדֵיהוֹן עַל רֵישׁ דִּכְרָא:
@84 וּנְכֵס וּנְסִיב משֶׁה מִן דְּמָא וִיהַב עַל רוּם אוּדְנָא דְאַהֲרֹן דְּיַמִּינָא וְעַל אִלְיוֹן יְדֵיהּ דְּיַמִּינָא וְעַל אִלְיוֹן רַגְלֵיהּ דְּיַמִּינָא:
@85 וְקָרִיב יָת בְּנֵי אַהֲרֹן וִיהַב משֶׁה מִן דְּמָא עַל רוּם אוּדְנֵהוֹן דְּיַמִּינָא וְעַל אִלְיוֹן יְדֵיהוֹן דְּיַמִּינָא וְעַל אִלְיוֹן רַגְלֵהוֹן דְּיָמִּינָא וּזְרַק משֶׁה יָת דְּמָא עַל מַדְבְּחָא סְחוֹר סְחוֹר:
@86 וּנְסִיב יָת תַּרְבָּא וְיָת אֲלִיתָא וְיָת כָּל תַּרְבָּא דִּי עַל גַּוָּא וְיָת חֲצַר כַּבְדָּא וְיָת תַּרְתֵּין כָּלְיָן וְיָת תַּרְבְּהֶן וְיָת שׁוֹקָא דְיַמִּינָא:
@87 וּמִסַּלָּא דְפַטִּירַיָּא דִּי קֳדָם יְיָ נְסִיב גְּרִצְתָּא פַטִּירָא חֲדָא וּגְרִצְתָּא דִלְחֵם מְשַׁח חֲדָא וְאֶסְפּוֹג חָד וְשַׁוִּי עַל תַּרְבַּיָּא וְעַל שׁוֹקָא דְיַמִּינָא:
@88 וִיהַב יָת כֹּלָּא עַל יְדֵי אַהֲרֹן וְעַל יְדֵי בְנוֹהִי וַאֲרֵם יָתְהוֹן אֲרָמָא קֳדָם יְיָ:
@89 וּנְסִיב משֶׁה יָתְהוֹן מֵעַל יְדֵיהוֹן וְאַסֵּק לְמַדְבְּחָא עַל עֲלָתָא קֻרְבָּנַיָּא אִנּוּן לְאִתְקַבָּלָא בְרַעֲוָא קֻרְבָּנָא הוּא קֳדָם יְיָ:
@90 וּנְסִיב משֶׁה יָת חֶדְיָא וַאֲרִימֵיהּ אֲרָמָא קֳדָם יְיָ מִדְּכַר קֻרְבָּנַיָּא לְמשֶׁה הֲוָה לָחֳלָק כְּמָא דִי פַקִּיד יְיָ יָת משֶׁה:
@91 וּנְסִיב משֶׁה מִמִּשְׁחָא דִרְבוּתָא וּמִן דְּמָא דִּי עַל מַדְבְּחָא וְאַדִּי עַל אַהֲרֹן עַל לְבוּשׁוֹהִי וְעַל בְּנוֹהִי וְעַל לְבוּשֵׁי בְנוֹהִי עִמֵּיהּ וְקַדִּישׁ יָת אַהֲרֹן יָת לְבוּשׁוֹהִי וְיָת בְּנוֹהִי וְיָת לְבוּשֵׁי בְנוֹהִי עִמֵּיהּ:
@92 וַאֲמַר משֶׁה לְאַהֲרֹן וְלִבְנוֹהִי בַּשִּׁילוּ יָת בִּסְרָא בִּתְרַע מַשְׁכַּן זִמְנָא וְתַמָּן תֵּיכְלוּן יָתֵיהּ וְיָת לַחְמָא דִּי בְּסַל קֻרְבָּנַיָּא כְּמָא דִי פַקֵּדִית לְמֵימַר אַהֲרֹן וּבְנוֹהִי יֵיכְלֻנֵּיהּ:
@93 וּדְאִשְׁתָּאַר בְּבִשְׂרָא וּבְלַחְמָא בְּנוּרָא תּוֹקְדוּן:
@94 וּמִתְּרַע מַשְׁכַּן זִמְנָא לָא תִפְּקוּן שִׁבְעָא יוֹמִין עַד יוֹם מִשְׁלַם יוֹמֵי קֻרְבָּנֵיכוֹן אֲרֵי שִׁבְעָא יוֹמִין יְקָרֵב יָת קֻרְבָּנְכוֹן:
@95 כְּמָא דִי עֲבַד בְּיוֹמָא הָדֵין פַּקִּיד יְיָ לְמֶעְבַּד לְכַפָּרָא עֲלֵיכוֹן:
@96 וּבִתְרַע מַשְׁכַּן זִמְנָא תֵּיתְבוּן יְמָם וְלֵילֵי שִׁבְעָא יוֹמִין וְתִטְּרוּן יָת מַטְּרַת מֵימְרָא דַיְיָ וְלָא תְמוּתוּן אֲרֵי כֵן אִתְפַּקָּדִית:
@97 וַעֲבַד אַהֲרֹן וּבְנוֹהִי יָת כָּל פִּתְגָּמַיָּא דִּי פַקִּיד יְיָ בִּידָא דְמשֶׁה:

@2 **צו את אהרן.** אֵין צַו אֶלָּא לְשׁוֹן זֵרוּז מִיָּד וּלְדוֹרוֹת; אָמַר רַבִּי שִׁמְעוֹן, בְּיוֹתֵר צָרִיךְ הַכָּתוּב לְזָרֵז בְּמָקוֹם שֶׁיֵּשׁ בּוֹ חֶסְרוֹן כִּיס (ספרא):
@2 **זאת תורת העלה וגו'.** הֲרֵי הָעִנְיָן הַזֶּה בָּא לְלַמֵּד עַל הֶקְטֵר חֲלָבִים וְאֵבָרִים שֶׁיְּהֵא כָּשֵׁר כָּל הַלַּיְלָה, וּלְלַמֵּד עַל הַפְּסוּלִין אֵי זֶה אִם עָלָה יֵרֵד, וְאֵי זֶה אִם עָלָה לֹא יֵרֵד, שֶׁכָּל תּוֹרָה לְרַבּוֹת הוּא בָּא, לוֹמַר — תּוֹרָה אַחַת לְכָל הָעוֹלִים, וַאֲפִלוּ פְּסוּלִין, שֶׁאִם עָלוּ לֹא יֵרְדוּ (שם):
@2 **הוא העלה.** לְמַעֵט אֶת הָרוֹבֵעַ וְאֶת הַנִּרְבָּע וְכַיּוֹצֵא בָּהֶן, שֶׁלֹּא הָיָה פְּסוּלָן בַּקֹּדֶשׁ, שֶׁנִּפְסְלוּ קֹדֶם שֶׁבָּאוּ לָעֲזָרָה (שם ח):
@3 **מדו בד.** הִיא הַכֻּתֹּנֶת, וּמָה תַּ"ל מִדּוֹ? שֶׁתְּהֵא כְּמִדָּתוֹ (שם):
@3 **על בשרו.** שֶׁלֹּא יְהֵא דָּבָר חוֹצֵץ בֵּינְתַיִם (זבחים י"ט):
@3 **והרים את הדשן.** הָיָה חוֹתֶה מְלֹא מַחְתָּה מִן הַמְאֻכָּלוֹת הַפְּנִימִיּוֹת וְנוֹתְנָן בְּמִזְרָחוֹ שֶׁל כֶּבֶשׁ (תמיד כ"ח):
@3 **הדשן אשר תאכל האש את העלה.** וַעֲשָׂאַתָּה דֶּשֶׁן, מֵאוֹתוֹ דֶּשֶׁן יָרִים תְּרוּמָה **ושמו אצל המזבח** :
@3 [ **על המזבח.** מָצָא אֵבָרִים שֶׁעֲדַיִן לֹא נִתְאַכְּלוּ, מַחֲזִירָן עַל מִזְבֵּחַ לְאַחַר שֶׁחָתָה גֶּחָלִים אֵילָךְ וָאֵילָךְ וְנָטַל מִן הַפְּנִימִיּוֹת, שֶׁנֶּאֱמַר אֶת הָעֹלָה עַל הַמִּזְבֵּחַ]:
@4 **ופשט את בגדיו.** אֵין זוֹ חוֹבָה אֶלָּא דֶּרֶךְ אֶרֶץ, שֶׁלֹּא יְלַכְלֵךְ בְּהוֹצָאַת הַדֶּשֶׁן בְּגָדִים שֶׁהוּא מְשַׁמֵּשׁ בָּהֶן תָּמִיד — בְּגָדִים שֶׁבִּשֵּׁל בָּהֶן קְדֵרָה לְרַבּוֹ, אַל יִמְזֹג בָּהֶן כּוֹס לְרַבּוֹ, לְכָךְ וְלָבַשׁ בְּגָדִים אֲחֵרִים פְּחוּתִין מֵהֶם (ספרא):
@4 **והוציא את הדשן.** הַצָּבוּר בַּתַּפּוּחַ, כְּשֶׁהוּא הַרְבֵּה וְאֵין מָקוֹם לַמַּעֲרָכָה, מוֹצִיאוֹ מִשָּׁם; וְאֵין זֶה חוֹבָה לְכָל יוֹם, אֲבָל הַתְּרוּמָה חוֹבָה בְּכָל יוֹם (תמיד כ"ח):
@5 **והאש על המזבח תוקד בו.** רִבָּה כָּאן יְקִידוֹת הַרְבֵּה — **על מוקדה, ואש המזבח תוקד בו, והאש על המזבח תוקד בו, אש תמיד תוקד על המזבח** , כֻּלָּן נִדְרְשׁוּ בְּמַסֶּכֶת יוֹמָא (דף מ"ה), שֶׁנֶּחְלְקוּ רַבּוֹתֵינוּ בְּמִנְיַן הַמַּעֲרָכוֹת שֶׁהָיוּ שָׁם:
@5 **וערך עליה העלה.** עוֹלַת תָּמִיד הִיא תִּקְדֹּם (מנחות מ"ט):
@5 **חלבי השלמים.** אִם יָבִיאוּ שָׁם שְׁלָמִים, וְרַבּוֹתֵינוּ לָמְדוּ מִכָּאן "עָלֶיהָ" — עַל עוֹלַת הַבֹּקֶר הַשְׁלֵם כָּל הַקָּרְבָּנוֹת כֻּלָּם, מִכָּאן שֶׁלֹּא יְהֵא דָּבָר מְאֻחָר לְתָמִיד שֶׁל בֵּין הָעַרְבָּיִם (ספרא):
@6 **אש תמיד.** אֵשׁ שֶׁנֶּאֱמַר בּוֹ תָּמִיד, הִיא שֶׁמַּדְלִיקִין בָּהּ אֶת הַנֵּרוֹת שֶׁנֶּאֱמַר בָּה לְהַעֲלֹת נֵר תָּמִיד (שמות כ"ז), אַף הִיא מֵעַל מִזְבֵּחַ הַחִיצוֹן תּוּקַד (יומא מ"ה):
@6 **לא תכבה.** הַמְכַבֶּה אֵשׁ עַל הַמִּזְבֵּחַ עוֹבֵר בִּשְׁנֵי לָאוִין:
@7 **וזאת תורת המנחה.** תּוֹרָה אַחַת לְכֻלָּן — לְהַטְעִינָן שֶׁמֶן וּלְבוֹנָה הָאֲמוּרִין בָּעִנְיָן, שֶׁיָּכוֹל אֵין לִי טְעוּנוֹת שֶׁמֶן וּלְבוֹנָה אֶלָּא מִנְחַת יִשְֹרָאֵל שֶׁהִיא נִקְמֶצֶת, מִנְחַת כֹּהֲנִים שֶׁהִיא כָּלִיל מִנַּיִן? תַּ"ל תּוֹרַת (ספרא):
@7 **הקרב אתה.** הִיא הַגָּשָׁה בְּקֶרֶן דְּרוֹמִית מַעֲרָבִית (שם):
@7 **לפני ה'.** הוּא מַעֲרָב שֶׁהוּא לְצַד אֹהֶל מוֹעֵד:
@7 **אל פני המזבח.** הוּא הַדָּרוֹם, שֶׁהוּא פָּנָיו שֶׁל מִזְבֵּחַ, שֶׁהַכֶּבֶשׁ נָתוּן לְאוֹתוֹ הָרוּחַ (סוטה י"ד):
@8 **והרים ממנו.** מִן הַמְחֻבָּר — שֶׁיְּהֵא עִשָּׂרוֹן שָׁלֵם בְּבַת אַחַת בִּשְׁעַת קְמִיצָה (ספרא):
@8 **בקמצו.** שֶׁלֹּא יַעֲשֶֹה מִדָּה לַקֹּמֶץ (שם):
@8 **מסלת המנחה ומשמנה.** מִכָּאן שֶׁקּוֹמֵץ מִמָּקוֹם שֶׁנִּתְרַבָּה שַׁמְנָהּ (סוטה י"ד):
@8 **המנחה.** שֶׁלֹּא תְּהֵא מְעֹרֶבֶת בְּאַחֶרֶת (ספרא):
@8 **ואת כל הלבנה אשר על המנחה והקטיר.** מְלַקֵּט אֶת לְבוֹנָתָהּ לְאַחַר קְמִיצָה וּמַקְטִירוֹ; וּלְפִי שֶׁלֹּא פֵּרֵשׁ כֵּן אֶלָּא בְּאַחַת מִן הַמְּנָחוֹת בְּוַיִּקְרָא, הֻצְרַךְ לִשְׁנוֹת פָּרָשָׁה זוֹ, לִכְלֹל כָּל הַמְּנָחוֹת כְּמִשְׁפָּטָן:
@9 **במקום קדש.** וְאֵיזֶהוּ? בַּחֲצַר אֹהֶל מוֹעֵד:
@10 **לא תאפה חמץ חלקם.** אַף הַשְּׁיָרִים אֲסוּרִים בְּחָמֵץ (מנחות נ"ה):
@10 **כחטאת וכאשם.** מִנְחַת חוֹטֵא הֲרֵי הִיא כְּחַטָּאת, לְפִיכָךְ קְמָצָהּ שֶׁלֹא לִשְׁמָהּ פְּסוּלָה, מִנְחַת נְדָבָה הֲרֵי הִיא כְּאָשָׁם, לְפִיכָךְ קְמָצָהּ שֶׁלֹּא לִשְׁמָהּ כְּשֵׁרָה (ספרא):
@11 **כל זכר.** אֲפִלּוּ בַּעַל מוּם; לָמָּה נֶאֱמַר? אִם לַאֲכִילָה הֲרֵי כְּבָר אָמוּר, לֶחֶם אֱלֹהָיו מִקָּדְשֵׁי הַקֳּדָשִׁים וְגוֹ' (ויקרא כ"א), אֶלָּא לְרַבּוֹת בַּעֲלֵי מוּמִין לְמַחֲלֹקֶת (ספרא):
@11 **כל אשר יגע וגו'.** קָדָשִׁים קַלִּים אוֹ חֻלִּין שֶׁיִּגְּעוּ בָּהּ וְיִבְלְעוּ מִמֶּנָּה:
@11 **יקדש.** לִהְיוֹת כָּמוֹהָ, שֶׁאִם פְּסוּלָה יִפָּסְלוּ, וְאִם כְּשֵׁרָה יֵאָכְלוּ כְּחֹמֶר הַמִּנְחָה (שם):
@13 **זה קרבן אהרן ובניו.** אַף הַהֶדְיוֹטוֹת מַקְרִיבִין עֲשִׂירִית הָאֵפָה בַּיּוֹם שֶׁהֵן מִתְחַנְּכִין לָעֲבוֹדָה, אֲבָל כֹּהֵן גָּדוֹל בְּכָל יוֹם, שֶׁנֶּאֱמַר מִנְחָה תָּמִיד וְגוֹ' וְהַכֹּהֵן הַמָּשִׁיחַ תַּחְתָּיו מִבָּנָיו וְגוֹ' חָק עוֹלָם:
@14 **מרבכת.** חֲלוּטָה בְּרוֹתְחִין כָּל צָרְכָּהּ (שם):
@14 **תפיני.** אֲפוּיָה אֲפִיּוֹת הַרְבֵּה — אַחַר חֲלִיטָתָהּ אוֹפָהּ בַּתַּנּוּר וְחוֹזֵר וּמְטַגְּנָהּ בַּמַּחֲבַת (מנחות נ'):
@14 **מנחת פתים.** מְלַמֵּד שֶׁטְּעוּנָה פְּתִיתָה:
@15 **המשיח תחתיו מבניו.** הַמָּשִׁיחַ מִבָּנָיו תַּחְתָּיו:
@15 **כליל תקטר.** אֵין נִקְמֶצֶת לִהְיוֹת שְׁיָרֶיהָ נֶאֱכָלִין אֶלָּא כֻּלָּהּ כָּלִיל, וְכֵן כָּל מִנְחַת כֹּהֵן שֶׁל נְדָבָה כָּלִיל תִּהְיֶה:
@16 **כליל.** כֻּלָּהּ שָׁוָה לְגָבוֹהַּ:
@19 **המחטא אתה.** הָעוֹבֵד עֲבוֹדוֹתֶיהָ — שֶׁהִיא נַעֲשֵׂית חַטָּאת עַל יָדוֹ:
@19 **המחטא אתה יאכלנה.** הָרָאוּי לַעֲבוֹדָה; יָצָא טָמֵא בִּשְׁעַת זְרִיקַת דָּמִים, שֶׁאֵינוֹ חוֹלֵק בַּבָּשָׂר; וְאִי אֶפְשָׁר לוֹמַר שֶׁאוֹסֵר שְׁאָר כֹּהֲנִים בַּאֲכִילָתָהּ חוּץ מִן הַזּוֹרֵק דָּמָהּ, שֶׁהֲרֵי נֶאֱמַר לְמַטָּה כָּל זָכָר בַּכֹּהֲנִים יֹאכַל אֹתָהּ (זבחים צ"ט):
@20 **כל אשר יגע בבשרה.** כָּל דְּבַר אֹכֶל אֲשֶׁר יִגַּע וְיִבְלַע מִמֶּנָּה:
@20 **יקדש.** לִהְיוֹת כָּמוֹהָ — אִם פְּסוּלָה תִּפָּסֵל, וְאִם הִיא כְּשֵׁרָה, תֵּאָכֵל כַּחֹמֶר שֶׁבָּהּ:
@20 **ואשר יזה מדמה על הבגד.** וְאִם הֻזָּה מִדָּמָהּ עַל הַבֶּגֶד, אוֹתוֹ מְקוֹם הַדָּם שֶׁבַּבֶּגֶד אֲשֶׁר יִזֶּה עָלֶיה, תְּכַבֵּס בְּתוֹךְ הָעֲזָרָה:
@20 **אשר יזה.** יְהֵא נִזֶּה, כְּמוֹ וְלֹא יִטֶּה לָאָרֶץ מִנְלָם (איוב ט"ו) — יְהֵא נָטוּי:
@21 **ישבר.** לְפִי שֶׁהַבְּלִיעָה שֶׁנִּבְלַעַת בּוֹ נַעֲשֶׂה נוֹתָר, וְהוּא הַדִּין לְכָל הַקֳּדָשִׁים:
@21 **ומרק.** לְשׁוֹן תַּמְרוּקֵי הַנָּשִׁים (אסתר ב'), אשקור"מנט בְּלַעַז:
@21 **ומרק ושטף.** לִפְלֹט אֶת בְּלִיעָתוֹ, אֲבָל כְּלִי חֶרֶס לִמֶּדְךָ הַכָּתוּב כָּאן שֶׁאֵינוֹ יוֹצֵא מִידֵי דָּפְיוֹ לְעוֹלָם (עבודה זרה ל"ד):
@22 **כל זכר בכהנים יאכל אתה.** הָא לָמַדְתָּ שֶׁהַמְחַטֵּא אוֹתָהּ הָאָמוּר לְמַעְלָה לֹא לְהוֹצִיא שְׁאָר הַכֹּהֲנִים, אֶלָּא לְהוֹצִיא אֶת שֶׁאֵינוֹ רָאוּי לְחִטּוּי:
@23 **וכל חטאת וגו'.** שֶׁאִם הִכְנִיס מִדַּם חַטָּאת הַחִיצוֹנָה לִפְנִים פְּסוּלָה:
@23 **וכל.** לְרַבּוֹת שְׁאָר קָדָשִׁים (ספרא):
@24 **קדש קדשים הוא.** הוּא קָרֵב וְאֵין תְּמוּרָתוֹ קְרֵבָה (ספרא):
@25 **ישחטו.** רִבָּה לָנוּ שְׁחִיטוֹת הַרְבֵּה; לְפִי שֶׁמָּצִינוּ אָשָׁם בְּצִבּוּר, נֶאֱמַר "יִשְׁחֲטוּ" — רַבִּים, וּתְלָאוֹ בְּעוֹלָה, לְהָבִיא עוֹלַת צִבּוּר לַצָּפוֹן:
@26 **ואת כל חלבו וגו'.** עַד כָּאן לֹא נִתְפָּרְשׁוּ אֵמוּרִין בָּאָשָׁם, לְכָךְ הֻצְרַךְ לְפָרְשָׁם כָּאן, אֲבָל חַטָּאת כְּבָר נִתְפָּרֵשׁ בָּהּ בְּפָרָשַׁת וַיִּקְרָא:
@26 **את האליה.** לְפִי שֶׁאָשָׁם אֵינוֹ בָּא אֶלָּא אַיִל אוֹ כֶּבֶשׂ, וְאַיִל וְכֶבֶשׂ נִתְרַבּוּ בְּאַלְיָה:
@28 **אשם הוא.** עַד שֶׁיִּנָּתֵק שְׁמוֹ מִמֶּנּוּ, לִמֵּד עַל אָשָׁם שֶׁמֵּתוּ בְּעָלָיו אוֹ שֶׁנִּתְכַּפְּרוּ בְּעָלָיו, אַעַ"פִּי שֶׁעוֹמֵד לִהְיוֹת דָּמָיו עוֹלֶה לְקַיִץ הַמִּזְבֵּחַ, אִם שְׁחָטוֹ סְתָם, אֵינוֹ כָּשֵׁר לְעוֹלָה קֹדֶם שֶׁנִּתַּק לִרְעִיָּה; וְאֵינוֹ בָּא לְלַמֵּד עַל הָאָשָׁם שֶׁיְּהֵא פָּסוּל שֶׁלֹּא לִשְׁמוֹ — כְּמוֹ שֶׁדָּרְשׁוּ הוּא הַכָּתוּב בַּחַטָּאת — לְפִי שֶׁאָשָׁם לֹא נֶאֱמַר בּוֹ אָשָׁם הוּא אֶלָּא לְאַחַר הַקְטָרַת אֵמוּרִין, וְהוּא עַצְמוֹ שֶׁלֹּא הֻקְטְרוּ אֵמוּרָיו כָּשֵׁר (זבחים ה'):
@29 **קדש קדשים הוא.** בְּתוֹרַת כֹּהֲנִים הוּא נִדְרָשׁ:
@30 **תורה אחת להם.** בְּדָבָר זֶה:
@30 **הכהן אשר יכפר בו.** הָרָאוּי לְכַפָּרָה חוֹלֵק בּוֹ, פְּרָט לִטְבוּל יוֹם וּמְחֻסַּר כִּפּוּרִים וְאוֹנֵן (ספרא):
@31 **עור העלה אשר הקריב לכהן לו יהיה.** פְּרָט לִטְבוּל יוֹם וּמְחֻסַּר כִּפּוּרִים וְאוֹנֵן שֶׁאֵין חוֹלְקִים בָּעוֹרוֹת (שם):
@32 **לכהן המקריב אתה וגו'.** יָכוֹל לוֹ לְבַדּוֹ, תַּ"ל **לכל בני אהרן תהיה** , יָכוֹל לְכֻלָּן, תַּ"ל **לכהן המקריב** , הָא כֵּיצַד? לְבֵית אָב שֶׁל יוֹם שֶׁמַּקְרִיבִין אוֹתָהּ (שם):
@33 **בלולה בשמן.** זוֹ מִנְחַת נְדָבָה:
@33 **וחרבה.** זוֹ מִנְחַת חוֹטֵא וּמִנְחַת קְנָאוֹת שֶׁאֵין בָּהֶן שֶׁמֶן:
@35 **אם על תודה יקריבנו.** אִם עַל דְּבַר הוֹדָאָה עַל נֵס שֶׁנַּעֲשָׂה לוֹ, כְּגוֹן יוֹרְדֵי הַיָּם וְהוֹלְכֵי מִדְבָּרוֹת וַחֲבוּשֵׁי בֵּית הָאֲסוּרִים וְחוֹלֶה שֶׁנִּתְרַפֵּא — שֶׁהֵן צְרִיכִין לְהוֹדוֹת, שֶׁכָּתוּב בָּהֶן יוֹדוּ לַה' חַסְדּוֹ וְנִפְלְאוֹתָיו לִבְנֵי אָדָם וְיִזְבְּחוּ זִבְחֵי תוֹדָה (תהילים ק"ז) — אִם עַל אַחַת מֵאֵלֶּה נָדַר שְׁלָמִים הַלָּלוּ, שַׁלְמֵי תּוֹדָה הֵן, וּטְעוּנוֹת לֶחֶם הָאָמוּר בָּעִנְיָן, וְאֵין נֶאֱכָלִין אֶלָּא לְיוֹם וְלַיְלָה, כְּמוֹ שֶׁמְּפֹרָשׁ כָּאן:
@35 **והקריב על זבח התודה.** אַרְבָּעָה מִינֵי לֶחֶם — חַלּוֹת וּרְקִיקִין וּרְבוּכָה, שְׁלוֹשָׁה מִינֵי מַצָּה, וּכְתִיב עַל חַלֹּת לֶחֶם חָמֵץ וְגוֹ'; וְכָל מִין וָמִין עֶשֶׂר חַלּוֹת, כָּךְ מְפֹרָשׁ בִּמְנָחוֹת, וְשִׁעוּרָן חָמֵשׁ סְאִין יְרוּשַׁלְמִיּוֹת, שֶׁהֵן ו' מִדְבָּרִיּוֹת, כ' עִשָּׂרוֹן (מנחות ע"ו):
@35 **מרבכת.** לֶחֶם חָלוּט בְּרוֹתְחִין כָּל צָרְכּוֹ:
@36 **יקריב קרבנו על זבח.** מַגִּיד שֶׁאֵין הַלֶּחֶם קָדוֹשׁ קְדֻשַּׁת הַגּוּף — לִפָּסֵל בְּיוֹצֵא וּטְבוּל יוֹם וּמִלָּצֵאת לְחֻלִּין בְּפִדְיוֹן — עַד שֶׁיִּשָּׁחֵט הַזֶּבַח (ספרא):
@37 **אחד מכל קרבן.** לֶחֶם אֶחָד מִכָּל מִין וָמִין יִטֹּל תְּרוּמָה לַכֹּהֵן הָעוֹבֵד עֲבוֹדָתוֹ, וְהַשְּׁאָר נֶאֱכָל לַבְּעָלִים (מנחות ע"ז); וּבָשָׂר לַבְּעָלִים חוּץ מֵחָזֶה וְשׁוֹק שֶׁבָּהּ, כְּמוֹ שֶׁמְּפֹרָשׁ לְמַטָּה תְּנוּפַת חָזֶה וְשׁוֹק בִּשְׁלָמִים, וְהַתּוֹדָה קְרוּיָה שְׁלָמִים:
@38 **ובשר זבח תודת שלמיו.** יֵשׁ כָּאן רִבּוּיִין הַרְבֵּה, לְרַבּוֹת חַטָּאת וְאָשָׁם וְאֵיל נָזִיר וַחֲגִיגַת אַרְבָּעָה עָשָׂר שֶׁיִּהְיוּ נֶאֱכָלִין לְיוֹם וְלַיְלָה (ספרא):
@38 **ביום קרבנו יאכל.** וְכִזְמַן בְּשָׂרָהּ זְמַן לַחְמָהּ:
@38 **לא יניח ממנו עד בקר.** אֲבָל אוֹכֵל הוּא כָּל הַלַּיְלָה, אִם כֵּן לָמָּה אָמְרוּ עַד חֲצוֹת? כְּדֵי לְהַרְחִיק אָדָם מִן הָעֲבֵרָה (שם):
@39 **ואם נדר או נדבה.** שֶׁלֹּא הֱבִיאָהּ עַל הוֹדָאָה שֶׁל נֵס, אֵינָהּ טְעוּנָה לֶחֶם, וְנֶאֱכֶלֶת לִשְׁנֵי יָמִים כְּמוֹ שֶׁמְּפֹרָשׁ בָּעִנְיָן:
@39 **וממחרת והנותר ממנו** בָּרִאשׁוֹן **יאכל.** וי"ו זוֹ יְתֵרָה הִיא, וְיֵשׁ כָּמוֹהָ הַרְבֵּה בַּמִּקְרָא, כְּגוֹן וְאֵלֶה בְנֵי צִבְעוֹן וְאַיָּה וַעֲנָה (בראשית ל"ו), תֵּת וְקֹדֶשׁ וְצָבָא מִרְמָס (דניאל ח'):
@41 **ואם האכל יאכל וגו'.** בִּמְחַשֵּׁב בַּשְּׁחִיטָה לְאָכְלוֹ בַּשְּׁלִישִׁי הַכָּתוּב מְדַבֵּר; יָכוֹל אִם אָכַל מִמֶּנּוּ בַּשְּׁלִישִׁי יִפָּסֵל לְמַפְרֵעַ, תַּלְמוּד לוֹמַר הַמַּקְרִיב אֹתוֹ לֹא יֵחָשֵׁב — בִּשְׁעַת הַקְרָבָה הוּא נִפְסָל וְאֵינוֹ נִפְסָל בַּשְּׁלִישִׁי; וְכֵן פֵּרוּשׁוֹ: בִּשְׁעַת הַקְרָבָתוֹ לֹא תַּעֲלֶה זֹאת בְּמַחֲשָׁבָה, וְאִם חִשֵּׁב פִּגּוּל יִהְיֶה (זבחים כ"ט):
@41 **והנפש האכלת ממנו.** אֲפִלּוּ בְּתוֹךְ הַזְּמַן **עונה תשא** :
@42 **והבשר.** שֶׁל קֹדֶשׁ שְׁלָמִים **אשר יגע בכל טמא לא יאכל** :
@42 **והבשר.** לְרַבּוֹת אֵבֶר שֶׁיָּצָא מִקְצָתוֹ — שֶׁהַפְּנִימִי מֻתָּר (ספרא):
@42 **כל טהור יאכל בשר.** מַה תַּ"ל? לְפִי שֶׁנֶּאֱמַר וְדַם זְבָחֶיךָ יִשָּׁפֵךְ וְגוֹ' וְהַבָּשָֹר תֹּאכֵל (דברים י"ב), יָכוֹל לֹא יֹאכְלוּ שְׁלָמִים אֶלָּא הַבְּעָלִים, לְכָךְ נֶאֱמַר כָּל טָהוֹר יֹאכַל בָּשָֹר (ספרא):
@42 ( **והבשר כל טהור יאכל בשר.** כְּלוֹמַר, כָּל מַה שֶּׁאָסַרְתִּי לְךָ בְּחַטָּאת וְאָשָׁם, שֶׁאִם יָצְאוּ חוּץ לַקְּלָעִים אֲסוּרִין — כְּמוֹ שֶׁכָּתוּב בַּחֲצַר אֹהֶל מוֹעֵד יֹאכְלוּהָ (ויקרא ו') — בְּבָשָׂר זֶה אֲנִי אוֹמֵר לְךָ כָּל טָהוֹר יֹאכַל בָּשָׂר אֲפִלּוּ בְּכָל הָעִיר):
@43 **וטמאתו עליו.** בְּטֻמְאַת הַגּוּף הַכָּתוּב מְדַבֵּר, אֲבָל טָהוֹר שֶׁאָכַל אֶת הַטָּמֵא אֵינוֹ עָנוּשׁ כָּרֵת אֶלָּא אַזְהָרַת **והבשר אשר יגע בכל טמא וגו';** וְאַזְהָרַת טָמֵא שֶׁאָכַל אֶת הַטָּהוֹר אֵינָהּ מְפֹרֶשֶׁת בַּתּוֹרָה, אֶלָּא חֲכָמִים לְמָדוּהָ בִּגְזֵרָה שָׁוָה; שָׁלוֹשׁ כָּרֵתוֹת אֲמוּרוֹת בְּאוֹכְלֵי קָדָשִׁים בְּטֻמְאַת הַגּוּף, וּדְרָשׁוּם רַבּוֹתֵינוּ בִּשְׁבוּעוֹת אַחַת לִכְלָל, וְאַחַת לִפְרָט, וְאַחַת לְלַמֵּד עַל קָרְבָּן עוֹלֶה וְיוֹרֵד שֶׁלֹּא נֶאֱמַר אֶלָּא עַל טֻמְאַת מִקְדָּשׁ וְקָדָשָׁיו:
@47 **יעשה לכל מלאכה.** בָּא וְלִמֵּד עַל הַחֵלֶב שֶׁאֵינוֹ מְטַמֵּא טֻמְאַת נְבֵלוֹת:
@47 **ואכל לא תאכלהו.** אָמְרָה תּוֹרָה, יָבֹא אִסּוּר נְבֵלָה וּטְרֵפָה וְיָחוּל עַל אִסּוּר חֵלֶב, שֶׁאִם אֲכָלוֹ יִתְחַיֵּב אַף עַל לָאו שֶׁל נְבֵלָה, וְלֹא תֹּאמַר אֵין אִסּוּר חָל עַל אִסּוּר (זבחים ע'):
@49 **בכל מושבתיכם.** לְפִי שֶׁהִיא חוֹבַת הַגּוּף וְאֵינָהּ חוֹבַת קַרְקַע נוֹהֶגֶת בְּכָל מוֹשָׁבוֹת, וּבְמַסֶּכֶת קִדּוּשִׁין בְּפֶרֶק א' מְפֹרָשׁ לָמָּה הֻצְרַךְ לוֹמַר:
@49 **לעוף ולבהמה.** פְּרָט לְדַם דָּגִים וַחֲגָבִים (כריתות כ'):
@53 **ידיו תביאינה וגו'.** שֶׁתְּהֵא יַד הַבְּעָלִים מִלְּמַעְלָה, וְהַחֵלֶב וְהֶחָזוֹת נְתוּנִין בָּהּ, וְיַד כֹּהֵן מִלְּמַטָּה וּמְנִיפָן (מנחות ס"א):
@53 **את אשי ה'.** וּמָה הֵן הָאִשִּׁים?
@53 **את החלב על החזה יביאנו.** כְּשֶׁמְּבִיאוֹ מִבֵּית הַמִּטְבָּחַיִם נוֹתֵן חֵלֶב עַל הֶחָזֶה, וּכְשֶׁנּוֹתְנוֹ לְיַד הַכֹּהֵן הַמֵּנִיף נִמְצָא הֶחָזֶה לְמַעְלָה וְהַחֵלֶב לְמַטָּה, וְזֶהוּ הָאָמוּר בְּמָקוֹם אַחֵר שׁוֹק הַתְּרוּמָה וַחֲזֵה הַתְּנוּפָה עַל אִשֵּׁי הַחֲלָבִים יָבִיאוּ לְהָנִיף וְגוֹ' (ויקרא י'), וּלְאַחַר הַתְּנוּפָה נוֹתְנוֹ לַכֹּהֵן הַמַּקְטִיר, וְנִמְצָא הֶחָזֶה לְמַטָּה, וְזֶהוּ שֶׁנֶּאֱמַר וַיָּשִֹימוּ אֶת הַחֲלָבִים עַל הֶחָזוֹת וַיַּקְטֵר הַחֲלָבִים הַמִּזְבֵּחָה (שם ט'), לִמְּדָנוּ שֶׁשְּׁלוֹשָׁה כֹּהֲנִים זְקוּקִין לָהּ, כָּךְ מְפֹרָשׁ בִּמְנָחוֹת:
@53 **את החלב על החזה יביאנו.** וְאֶת הֶחָזֶה לָמָּה מֵבִיא? לְהָנִיף אוֹתוֹ הוּא מְבִיאוֹ וְלֹא שֶׁיְּהֵא הוּא מֵהָאִשִּׁים: לְפִי שֶׁנֶּאֱמַר **את אשי ה' את החלב על החזה** יָכוֹל שֶׁיְּהֵא אַף הֶחָזֶה לָאִשִּׁים, לְכָךְ נֶאֱמַר **את החזה להניף וגו'** :
@54 **והקטיר הכהן את החלב.** וְאַחַ"כַּ **והיה החזה לאהרן** , לִמְּדָנוּ שֶׁאֵין הַבָּשָׂר נֶאֱכָל בְּעוֹד שֶׁהָאֵמוּרִים לְמַטָּה מִן הַמִּזְבֵּחַ (ספרא):
@55 **שוק.** מִן הַפֶּרֶק שֶׁל אַרְכֻּבָּה הַנִּמְכֶּרֶת עִם הָרֹאשׁ עַד הַפֶּרֶק הָאֶמְצָעִי שֶׁהוּא סֹבֶךְ שֶׁל רֶגֶל (חולין קל"ד):
@56 **המקריב את דם השלמים וגו'.** מִי שֶׁהוּא רָאוּי לִזְרִיקָתוֹ וּלְהַקְטִיר חֲלָבָיו, יָצָא טָמֵא בִּשְׁעַת זְרִיקַת דָּמִים אוֹ בִּשְׁעַת הֶקְטֵר חֲלָבִים שֶׁאֵינוֹ חוֹלֵק בַּבָּשָׂר (ספרא):
@57 **תנופה, תרומה.** מוֹלִיךְ וּמֵבִיא מַעֲלֶה וּמוֹרִיד (מנחות ס"ב):
@60 **ולמלואים.** לְיוֹם חִנּוּךְ הַכְּהֻנָּה:
@63 **קח את אהרן.** פָּרָשָׁה זוֹ נֶאֶמְרָה שִׁבְעַת יָמִים קֹדֶם הֲקָמַת הַמִּשְׁכָּן, שֶׁאֵין מֻקְדָּם וּמְאֻחָר בַּתּוֹרָה:
@63 **קח את אהרן.** קָחֶנּוּ בִדְבָרִים וּמָשְׁכֵהוּ:
@63 **ואת פר החטאת וגו'.** אֵלּוּ הָאֲמוּרִים בְּעִנְיַן צַוָּאַת הַמִּלּוּאִים בִּוְאַתָּה תְּצַוֶּה, וְעַכְשָׁיו בְּיוֹם רִאשׁוֹן לַמִּלּוּאִים חָזַר וְזֵרְזוֹ בִשְׁעַת מַעֲשֶֹה:
@64 **הקהל אל פתח אהל מועד.** זֶה אֶחָד מִן הַמְּקוֹמוֹת שֶׁהֶחֱזִיק מֻעָט אֶת הַמְרֻבֶּה (ויקרא רבה י'):
@66 **זה הדבר.** דְּבָרִים שֶׁתִּרְאוּ שֶׁאֲנִי עוֹשֶׂה לִפְנֵיכֶם, צִוַּנִי הַקָּבָּ"ה לַעֲשׂוֹת, וְאַל תֹּאמְרוּ לִכְבוֹדִי וְלִכְבוֹד אָחִי אֲנִי עוֹשֶֹׁה; כָּל הָעִנְיָן הַזֶּה פֵּרַשְׁתִּי בְּ"וְאַתָּה תְּצַוֶּה":
@69 **את האורים.** כְּתָב שֶׁל שֵׁם הַמְפֹרָשׁ:
@70 **וישם על המצנפת.** פְּתִילֵי תְכֵלֶת הַקְּבוּעִים בַּצִּיץ נָתַן עַל הַמִּצְנֶפֶת, נִמְצָא הַצִּיץ תָּלוּי בַּמִּצְנֶפֶת:
@72 **ויז ממנו על המזבח.** לֹא יָדַעְתִּי הֵיכָן נִצְטַוָּה בַּהַזָּאוֹת הַלָּלוּ:
@73 **ויצק, וימשח.** בַּתְּחִלָּה יוֹצֵק עַל רֹאשׁוֹ וְאַחַר כָּךְ נוֹתֵן בֵּין רִיסֵי עֵינָיו וּמוֹשֵׁךְ בְּאֶצְבָּעוֹ מִזֶּה לָזֶה (הוריות י"ב):
@74 **ויחבש.** לְשׁוֹן קְשִׁירָה:
@76 **ויחטא את המזבח.** חִטְּאוֹ וְטִהֲרוֹ מִזָּרוּת לִכָּנֵס לִקְדֻשָּׁה:
@76 **ויקדשהו.** בַּעֲבוֹדָה זוֹ:
@76 **לכפר עליו.** מֵעַתָּה כָּל הַכַּפָּרוֹת:
@77 **הכבד.** לְבַד הַכָּבֵד, שֶׁהָיָה נוֹטֵל מְעַט מִן הַכָּבֵד עִמָּהּ:
@83 **איל המלאים.** אֵיל הַשְּׁלָמִים, שֶׁמִּלּוּאִים לְשׁוֹן שְׁלָמִים, שֶׁמְּמַלְּאִין וּמַשְׁלִימִין אֶת הַכֹּהֲנִים בִּכְהֻנָּתָם:
@87 **וחלת לחם שמן.** הִיא רְבוּכָה שֶׁהָיָה מַרְבֶּה בָּהּ שֶׁמֶן כְּנֶגֶד הַחַלּוֹת וְהָרְקִיקִין, כָּךְ מְפֹרָשׁ בִּמְנָחוֹת (דף פ"ט):
@89 **ויקטר המזבחה.** מֹשֶׁה שִׁמֵּשׁ כָּל שִׁבְעַת יְמֵי הַמִּלּוּאִים בְּחָלוּק לָבָן (עבודה זרה ל"ד):
@89 **על העלה.** אַחַר הָעוֹלָה, וְלֹא מָצִינוּ שׁוֹק שֶׁל שְׁלָמִים קָרֵב בְּכָל מָקוֹם חוּץ מִזֶּה:
@95 **צוה ה' לעשת.** כָּל שִׁבְעַת הַיָּמִים; וְרַבּוֹתֵינוּ דָרְשׁוּ, **לעשת** — זֶה מַעֲשֵׂה פָרָה, **לכפר** — זֶה מַעֲשֵׂה יוֹם הַכִּפּוּרִים, וּלְלַמֵּד שֶׁכֹּהֵן גָּדוֹל טָעוּן פְּרִישָׁה קֹדֶם יוֹם הַכִּפּוּרִים שִׁבְעַת יָמִים, וְכֵן הַכֹּהֵן הַשּׂוֹרֵף אֶת הַפָּרָה (ספרא):
@96 **ולא תמותו.** הָא אִם לֹא תַעֲשׂוּ כֵן הֲרֵי אַתֶּם חַיָּבִים מִיתָה:
@97 **ויעש אהרן ובניו.** לְהַגִּיד שִׁבְחָן, שֶׁלֹא הִטּוּ יָמִין וּשְֹמֹאל:

@2 אָמַר הַכָּתוּב בְּפָרָשַׁת וַיִּקְרָא "דַּבֵּר אֶל בְּנֵי יִשְׂרָאֵל", כִּי שָׁם יְצַוֶּה בַּהֲבָאַת הַקָּרְבָּנוֹת וְיִשְׂרָאֵל מְבִיאִים אוֹתָם. וְכָאן אָמַר **צַו אֶת אַהֲרֹן** כִּי יְדַבֵּר בְּמַעֲשֵׂה הַקָּרְבָּנוֹת וְהַכֹּהֲנִים יַעֲשׂוּ אוֹתָם. וְכָתַב רַשִׁ"י (רש"י על ויקרא ו':ב') אֵין צַו אֶלָּא זֵרוּז, מִיָּד וּלְדוֹרוֹת, אָמַר רַבִּי שִׁמְעוֹן בְּיוֹתֵר הָיָה צָרִיךְ הַכָּתוּב לְזָרֵז בְּמָקוֹם שֶׁיֵּשׁ בּוֹ חֶסְרוֹן כִּיס. וּמִדְרָשׁוֹ שֶׁל רַבִּי שִׁמְעוֹן אֵינוֹ עַל זוֹ הַצַּוָּאָה, כִּי כָּאן אֵין בּוֹ חֶסְרוֹן כִּיס לִבְנֵי אַהֲרֹן הַמְּצֻוִּין בָּהּ, אֲבָל יֵשׁ לָהֶם רֶוַח וְשָׂכָר בְּכָל הַקָּרְבָּנוֹת גַּם בָּעוֹלָה, אֲבָל אָמַר תַּנָּא קַמָּא אֵין צַו אֶלָּא זֵרוּז מִיָּד וּלְדוֹרוֹת, לוֹמַר שֶׁהַפָּרָשִׁיּוֹת שֶׁיִּרְצֶה הַכָּתוּב לְזָרֵז בָּהֶם וְלוֹמַר שֶׁיַּעֲשֶׂה מִיָּד וְיִנְהַג הַדָּבָר לְדוֹרוֹת יֹאמַר בָּהֶן "צַו", וּבִשְׁאָר הַפָּרָשִׁיּוֹת יֹאמַר "דַּבֵּר אֶל בְּנֵי יִשְׂרָאֵל" אוֹ "אֱמֹר לָהֶם". וּבָא רַבִּי שִׁמְעוֹן לַחְלֹק וְלוֹמַר שֶׁפְּעָמִים יָבֹא הַלָּשׁוֹן הַזֶּה בְּדָבָר שֶׁאֵינוֹ מִיָּד וּלְדוֹרוֹת, בַּעֲבוּר שֶׁיֵּשׁ בּוֹ חֶסְרוֹן כִּיס, כְּגוֹן הַצַּוָּאָה הָאֲמוּרָה בְּשֶׁמֶן הַמָּאוֹר, וּכְגוֹן שֶׁאָמַר הַכָּתוּב "צַו אֶת בְּנֵי יִשְׂרָאֵל וְנָתְנוּ לַלְוִיִּם עָרִים לָשָׁבֶת". וְיִתָּכֵן שֶׁנֹּאמַר שֶׁיֵּשׁ בְּצַו זֶה חֶסְרוֹן כִּיס לַכֹּהֲנִים בַּעֲבוּר "זֶה קָרְבַּן אַהֲרֹן וּבָנָיו" הַנִּמְשָׁךְ בְּצַוָּאָה זוֹ. אֲבָל בִּתְחִלַּת סִפְרֵי בְּעִנְיַן מַחְלֹקֶת הִיא שְׁנוּיָה שָׁם:
@2 **זֹאת תּוֹרַת הָעוֹלָה** הֲרֵי הָעִנְיָן הַזֶּה בָּא לְלַמֵּד עַל הֶקְטֵר חֲלָבִים וְאֵבָרִים שֶׁהוּא כָּשֵׁר כָּל הַלַּיְלָה, וּלְלַמֵּד עַל הַפְּסוּלִים אֵיזֶה מֵהֶם אִם עָלָה יֵרֵד וְאֵיזֶה מֵהֶם אִם עָלָה לֹא יֵרֵד, שֶׁכָּל "תּוֹרַת" לְרַבּוֹת הוּא, תּוֹרָה אַחַת לְכָל הָעוֹלִים וַאֲפִלוּ פְּסוּלִים שֶׁאִם עָלוּ לֹא יֵרְדוּ, לְשׁוֹן רַשִׁ"י (רש"י על ויקרא ו':ב'). וְאֵין הַתּוֹרָה הַזּוֹ לְכָל הָעוֹלִים אֶלָּא לְכָל הָעוֹלוֹת, שֶׁהַנְּסָכִים אִם עָלוּ יֵרְדוּ, וַאֲפִילּוּ נְסָכִים כְּשֵׁרִים וְהַזֶּבַח פָּסוּל אוֹ הַזֶּבַח כָּשֵׁר וּנְסָכִים פְּסוּלִים וְכָל שֶׁכֵּן שְׁנֵיהֶם פְּסוּלִים, בְּכֻלָּן הַזֶּבַח לֹא יֵרֵד וּנְסָכִים יֵרְדוּ, שֶׁזֶּהוּ רִבּוּיוֹ שֶׁל מִקְרָא, "תּוֹרַת הָעוֹלָה" - תּוֹרָה אַחַת לְכָל הָעוֹלוֹת וְלֹא לַנְּסָכִים וְלֹא לַדָּם, כְּדִבְרֵי ר' יְהוֹשֻׁעַ (בת"כ ובזבחים ט א). וְהִנֵּה הַכָּתוּב הַזֶּה מְלַמֵּד שֶׁלֹּא נַקְרִיב הָעוֹלָה בַּלַּיְלָה, אֲבָל אִם נִשְׁחֲטָה וְזָרַק דָּמָהּ בַּיּוֹם נַקְטִיר אֵיבָרֶיהָ כָּל הַלַּיְלָה וְכֵן חֶלְבֵי הַשְּׁלָמִים. וּפֵרוּשׁ "הִיא הָעוֹלָה" כְּמוֹ תִּהְיֶה הָעֹלָה עַל מוֹקְדָה עַל הַמִּזְבֵּחַ כָּל הַלַּיְלָה, וְאָמַר "הִיא" לַמִּעוּט שֶׁדָּרְשׁוּ בּוֹ, וּכְפִי הַמִּדְרָשׁ (בת"כ כאן) אֵין הַכָּתוּב מְלַמֵּד שֶׁנַּעֲלֶה הָאֵבָרִים מִן הָאָרֶץ לַמִּזְבֵּחַ בַּלַּיְלָה, שֶׁכְּבָר לָמְדוּ זֶה מִפָּסוּק אַחֵר (שמות כג יח), "לֹא יָלִין חֵלֶב חַגִּי עַד בֹּקֶר", כִּי מִשָּׁם יִלְמְדוּ (מכילתא משפטים כ יח) שֶׁיִּהְיוּ פְּסוּלִין בְּלִינָה עַל גַּבֵּי הָרִצְפָּה וּמַעֲלָן כָּל הַלַּיְלָה, וְכָאן יְדַבֵּר בָּאֵבָרִים שֶׁהֵן כְּבָר עַל גַּבֵּי הַמִּזְבֵּחַ בַּיּוֹם שֶׁמְּהַפְּכִין בָּהֶן כָּל הַלַּיְלָה עַד הַבֹּקֶר. וּלְכָךְ אָמַר "הָעוֹלָה", שֶׁכְּבָר עוֹלָה עַל גַּבֵּי הַמִּזְבֵּחַ. וְלִמֵּד עוֹד שֶׁאֲפִלּוּ פְּסוּלִין לֹא יֵרְדוּ וּבִלְבַד שֶׁיְּהוּ פְּסוּלָן בַּקֹּדֶשׁ, וְשֶׁהַנְּסָכִים יֵרְדוּ וְכֵן הַדָּם כְּמוֹ שֶׁכָּתַבְתִּי:
@2 **וְאֵשׁ הַמִּזְבֵּחַ תּוּקַד בּוֹ** יֹאמַר שֶׁתּוּקַד בַּמִּזְבֵּחַ כָּל הַלַּיְלָה, כִּי מִצְוָה שֶׁיָּשִׂימוּ בַּיּוֹם עֵצִים הַרְבֵּה כְּדֵי שֶׁלֹּא יִתְאַכְּלוּ לְגַמְרֵי וְיִכְבֶּה הָאֵשׁ מִמֶּנּוּ. וּלְפִי דַּעְתִּי מַה שֶׁאָמַר (ויקרא ו':ו') "אֵשׁ תָּמִיד תּוּקַד עַל הַמִּזְבֵּחַ לֹא תִכְבֶּה" מִצְוָה לַכֹּהֲנִים בְּקִיּוּם הָאֵשׁ, כְּמוֹ שֶׁאָמַר (ויקרא ו':ה') "וּבִעֵר עָלֶיהָ הַכֹּהֵן עֵצִים", וְצִוָּה שֶׁיִּזָּהֲרוּ בָּזֶה וְיַעַרְכוּ אֵשׁ וְעֵצִים הַרְבֵּה שֶׁתּוּקַד הָאֵשׁ תָּמִיד כָּל הַיּוֹם וְכָל הַלַּיְלָה, וְהִזְהִיר בְּלָאו שֶׁלֹּא תִּכְבֶּה לְעוֹלָם. וְהִנֵּה אִם נִתְעַצְּלוּ הַכֹּהֲנִים וְכָבְתָה הָאֵשׁ עָבְרוּ בְּלָאו. וּמִפְּנֵי זֶה אָמְרוּ רַבּוֹתֵינוּ (יומא מה) שֶׁהָיְתָה מַעֲרָכָה שְׁנִיָּה לְקִיּוּם הָאֵשׁ. וּמַה שֶׁאָמַר (ויקרא ו':ה') "וְהָאֵשׁ עַל הַמִּזְבֵּחַ תּוּקַד בּוֹ לֹא תִכְבֶּה" מִקְרָא יָתֵר, וְנִדְרָשׁ לְרַבּוֹתֵינוּ (תורת כהנים פרק ב ז) בְּכָל אָדָם, מְלַמֵּד שֶׁכָּל הַמְּכַבֶּה עוֹבֵר בְּלֹא תַּעֲשֶׂה, וַאֲפִילּוּ כִּבָּה מִן הַמַּעֲרָכָה גַּחֶלֶת אַחַת לוֹקֶה, בֵּין שֶׁכִּבָּה אוֹתָהּ בְּרֹאשׁוֹ שֶׁל מִזְבֵּחַ בֵּין שֶׁהוֹרִידָהּ וְכִבָּה אוֹתָהּ לְמַטָּה, וְכִמְדֻמֶּה לִי שֶׁאֵינוֹ עוֹבֵר אֶלָּא בְּלָאו אֶחָד:
@3 **וְלָבַשׁ הַכֹּהֵן מִדּוֹ בַד** הִיא הַכֻּתֹּנֶת, וּמַה תַּלְמוּד לוֹמַר "מִדּוֹ", שֶׁתְּהֵא כְּמִדָּתוֹ. **עַל בְּשָׂרוֹ** שֶׁלֹּא יְהֵא דָּבָר חוֹצֵץ בֵּינְתַיִם, לְשׁוֹן רַשִׁ"י (רש"י על ויקרא ו':ג'). וְהִנֵּה תְּרוּמַת הַדֶּשֶׁן צְרִיכָה בִּגְדֵי כְּהֻנָּה וְאֵין עֲבוֹדָה בִּשְׁנֵי הַבְּגָדִים מֵהֶם, אֲבָל הִזְכִּיר אֵלֶּה הַשְּׁנַיִם לְדָבָר שֶׁנִּתְחַדֵּשׁ בָּהֶם כָּאן, לוֹמַר שֶׁתְּהֵא הַכֻּתֹּנֶת כְּמִדָּתוֹ, וְהָעִנְיָן לוֹמַר שֶׁאִם הָיוּ מְסֻלָּקִין, קְצָרִים וְאֵינָן מַגִּיעִין עַד רַגְלָיו וְעָבַד בָּהֶן עֲבוֹדָתוֹ פְּסוּלָה, וְלִמֵּד שֶׁלֹּא יְהֵא בֵּינוֹ וְלֹא בֵּין הַמִּכְנָסַיִם לִבְשָׂרוֹ כְּלוּם, וְהוּא הַדִּין שֶׁצְּרִיכָה כָּל בִּגְדֵי כְּהֻנָּה, כִּי כֵּיוָן שֶׁהִזְכִּיר הַכָּתוּב שֶׁהִיא צְרִיכָה בְּגָדִים לָמַדְנוּ שֶׁהִיא צְרִיכָה אַרְבָּעָה לְהֶדְיוֹט וּשְׁמֹנֶה לְכֹהֵן גָּדוֹל. וְכֵן מְפֹרָשׁ בְּמַסֶּכֶת יוֹמָא בְּפֶרֶק שֵׁנִי (כג) וּבְתוֹרַת כֹּהֲנִים (צו ב א), מַה תַּלְמוּד לוֹמַר "יִלְבָּשׁ", לְהָבִיא אֶת הַמִּצְנֶפֶת וְאֶת הָאַבְנֵט. וְאוּנְקְלוֹס (תרגום אונקלוס על ויקרא ו':ג') תִּרְגֵּם "מִדּוֹ" - "לְבוּשִׁין", וְנִרְאֶה כִּי אֶצְלוֹ "מִדּוֹ" - שֵׁם יִכְלֹל כָּל בְּגָדָיו, כְּאִלּוּ אָמַר וְלָבַשׁ הַכֹּהֵן בִּגְדֵי בַּד, וְכֵן "מַדָּיו קְרוּעִים" (שמואל א ד יב), "שֶׁיֹּרֵד עַל פִּי מִדּוֹתָיו" (תהלים קלג ב), עַל פִּי מַלְבּוּשָׁיו, "חָגוּר מִדּוֹ לְבוּשׁוֹ" (שמואל ב כ ח), וְיִהְיֶה זֶה כְּדַעַת הָאוֹמֵר אַבְנֵטוֹ שֶׁל כֹּהֵן הֶדְיוֹט לֹא זֶהוּ אַבְנֵטוֹ שֶׁל כֹּהֵן גָּדוֹל (יומא יב):
@4 **וּפָשַׁט אֶת בְּגָדָיו** אֵין זֶה חוֹבָה אֶלָּא דֶּרֶךְ אֶרֶץ, שֶׁלֹּא יְלַכְלֵךְ בְּגָדִים שֶׁהוּא מְשַׁמֵּשׁ בָּהֶם בְּהוֹצָאַת הַדֶּשֶׁן, בְּגָדִים שֶׁבִּשֵּׁל בָּהֶן קְדֵרָה לְרַבּוֹ אַל יִמְזֹג בָּהֶן כּוֹס לְרַבּוֹ, לְכָךְ אָמַר "וְלָבַשׁ בְּגָדִים אֲחֵרִים" - פְּחוּתִים מֵהֶם, לְשׁוֹן רַשִׁ"י (רש"י על ויקרא ו':ד'). וְהַכַּוָּנָה לְרַבּוֹתֵינוּ בָּזֶה לוֹמַר שֶׁהוֹצָאַת הַדֶּשֶׁן צְרִיכָה בִּגְדֵי כְּהֻנָּה, וְאֵין "בְּגָדִים אֲחֵרִים" בִּגְדֵי חוֹל, אֲבָל לֹא יָדַעְתִּי מִנַּיִן אָמַר הָרַב שֶׁאֵינָהּ חוֹבָה, כִּי נִרְאֶה שֶׁמִּצְוָה הִיא עַל הַכֹּהֵן שֶׁהַבְּגָדִים שֶׁיַּעֲשֶׂה בָּהֶם הַקָּרְבָּנוֹת גַּם הֲרָמַת הַדֶּשֶׁן יִהְיוּ בְּגָדִים נְקִיִּים, לֹא יְשַׁמֵּשׁ בְּאוֹתָן אֲשֶׁר הוֹצִיא הַדֶּשֶׁן. וְהַמִּצְוָה מִדֶּרֶךְ מוּסַר הָעֶבֶד לְרַבּוֹ, וּלְכָךְ יִהְיוּ לַכֹּהֲנִים הַבְּגָדִים הַחֲמוּדוֹת לָעֲבוֹדוֹת וְהַפְּחוּתִים לְהוֹצָאַת הַדֶּשֶׁן. וְכָל זֶה לְפִי הַסְּבָרָא הַזּוֹ שֶׁכְּתָבָהּ הָרַב, אֲבָל יֵשׁ מֵרַבּוֹתֵינוּ שָׁם בְּמַסֶּכֶת יוֹמָא (יומא כ"ג) אוֹמֵר שֶׁאֵין הוֹצָאַת הַדֶּשֶׁן צְרִיכָה בִּגְדֵי כְּהֻנָּה, וְיֹאמַר "וְלָבַשׁ בְּגָדִים אֲחֵרִים" - בִּגְדֵי חוֹל. וּפְשׁוּטוֹ שֶׁל מִקְרָא בְּכָךְ הוּא שֶׁיְּצַוֶּה עָלָיו שֶׁלֹּא יְלַכְלֵךְ בִּגְדֵי הַבָּד בִּגְדֵי הַקֹּדֶשׁ בְּהוֹצָאַת הַדֶּשֶׁן אֲבָל יִלְבַּשׁ בִּגְדֵי חוֹל:
@7 **וְזֹאת תּוֹרַת הַמִּנְחָה** הוֹסִיפָהּ הַפָּרָשָׁה הַזּוֹ כְּפִי פְּשׁוּטָהּ אַרְבַּע מִצְוֹת בַּמִּנְחָה, שֶׁתְּהֵא נֶאֱכֶלֶת מַצּוֹת (ויקרא ו':ט'), וְשֶׁתְּהֵא נֶאֱכֶלֶת בַּחֲצַר אֹהֶל מוֹעֵד (שם), וְשֶׁיֹּאכַל אוֹתָהּ כָּל זָכָר בִּבְנֵי אַהֲרֹן (ויקרא ו':י"א), וְשֶׁיִּקְדַּשׁ כָּל אֲשֶׁר יִגַּע בָּהֶן (שם). וּכְפִי מִדְרָשׁוֹ דְּבָרִים הַרְבֵּה מְחֻדָּשִׁים בָּהּ, שֶׁאֲפִלּוּ מִנְחַת כֹּהֲנִים שֶׁאֵינָהּ נִקְמֶצֶת טְעוּנָה שֶׁמֶן וּלְבוֹנָה, וְשֶׁיַּגִּישׁ אוֹתָהּ לִפְנֵי ה' שֶׁהוּא קֶרֶן מַעֲרָבִית וְאֶל פְּנֵי הַמִּזְבֵּחַ שֶׁהוּא קֶרֶן דְּרוֹמִית, וְנִמְצָא שֶׁטְּעוּנָה הַגָּשָׁה לְקֶרֶן מַעֲרָבִית דְּרוֹמִית (זבחים סג), "וְהֵרִים מִמֶּנּוּ" - מִן הַמְחֻבָּר, שֶׁלֹּא יָבִיא עִשָּׂרוֹן אֶחָד בִּשְׁנֵי כֵּלִים (מנחות כד), וְשֶׁלֹּא יַעֲשֶֹה מִדָּה לַקֹּמֶץ (שם יט), וְאָמַר "לֹא תֵאָפֶה חָמֵץ" לְהַקִּישׁ כָּל הַמְּלָאכוֹת לָאֲפִיָּה, שֶׁאַף לִישָׁתָהּ וַעֲרִיכָתָהּ וְכָל מַעֲשֶׂה וּמַעֲשֶׂה שֶׁבָּהּ עוֹבֵר בְּלָאו וְלוֹקֶה עָלָיו בִּפְנֵי עַצְמוֹ (מנחות נה):
@10 **חֶלְקָם נָתַתִּי אֹתָהּ מֵאִשָּׁי** שֶׁאַף לְחַלֵּק אֵינָם רַשָּׁאִין אֶלָּא לְאַחַר מַתְּנוֹת הָאִשִּׁים, וּמִכָּאן לָמַדְנוּ לְכָל הַקֳּדָשִׁים, דִּכְתִיב "קֹדֶשׁ קָדָשִׁים הִיא" (תורת כהנים פרק ג ב). וְלֹא תֵאָפֶה חָמֵץ חֶלְקָם, שֶׁאַף הַשִּׁירַיִם אֲסוּרִים בְּחִמּוּץ (מנחות נה), וְכַחַטָּאת וְכָאָשָׁם לִמֵּד מַה חַטָּאת מִן חֻלִּין בַּיּוֹם וּבְיַד יְמָנִית אַף זוֹ מִן הַחֻלִּין בַּיּוֹם וּבְיַד יְמָנִית (תורת כהנים פ"ג ג). וְכָל זָכָר בִּבְנֵי אַהֲרֹן - שֶׁאֲפִילּוּ בַּעֲלֵי מוּמִין בַּמַּחְלֹקֶת (זבחים צח), וְהוֹסִיפָה בַּכֹּהֲנִים "וְכָל מִנְחַת כֹּהֵן כָּלִיל תִּהְיֶה לֹא תֵאָכֵל" (ויקרא ו':ט"ז), וְאָמַר הָרַב בַּמּוֹרֶה הַנְּבֻכִים (ג מו) כִּי הַטַּעַם בַּעֲבוּר שֶׁכָּל כֹּהֵן מַקְרִיב קָרְבָּנוֹ הוּא בְּעַצְמוֹ, וְאִם יַקְרִיב מִנְחָה וְיֹאכְלֶנָּה הוּא בְּעַצְמוֹ כְּאִלּוּ לֹא הִקְרִיב דָּבָר, כִּי מִנְחַת יָחִיד לֹא יַקְרִיב מִמֶּנָּה כִּי אִם הַלְּבוֹנָה וְהַקֹּמֶץ, וְלֹא דַּי מִעוּט זֶה הַקָּרְבָּן אֶלָּא שֶׁיֹּאכְלֶנּוּ וְיִדְמֶה שֶׁלֹּא הִקְרִיב קָרְבָּן כְּלָל, וְלָכֵן יִשְׂרְפוּ אֶת כֻּלָּהּ:
@18 **זֹאת תּוֹרַת הַחַטָּאת** הָיָה הַצִּוּוּי בְּסֵדֶר וַיִּקְרָא עוֹלָה וּמִנְחָה וְזֶבַח הַשְּׁלָמִים וְהַחַטָּאת וְהָאָשָׁם, כִּי בַּתְּחִלָּה דִּבֵּר בְּקָרְבְּנוֹת הַנְּדָבָה וְאַחֲרֵי כֵן בְּקָרְבְּנוֹת הַחוֹבָה עַל חֵטְא. אֲבָל בְּכָאן הָיָה הַבֵּאוּר לָעוֹלָה וְלַמִּנְחָה וְאח"כ בַּחַטָּאת וּבָאָשָׁם, כִּי רָצָה לְבָאֵר דִּינֵי קָדְשֵׁי קָדָשִׁים כִּי הַמִּשְׁפָּט אֶחָד לָהֶם, כְּמוֹ שֶׁאָמַר בַּמִּנְחָה (ויקרא ו':י') "קֹדֶשׁ קָדָשִׁים הִיא כַּחַטָּאת וְכָאָשָׁם", וְאַחֲרֵי כֵּן יְבָאֵר דִּין קָדָשִׁים קַלִּים. וְהִנֵּה יְחַדֵּשׁ בְּפָרָשָׁה זוֹ דְּבָרִים רַבִּים, "זֹאת תּוֹרַת הַחַטָּאת" - תּוֹרָה אַחַת לְכָל הַחַטָּאוֹת, שֶׁאַף חַטָּאוֹת הַפְּנִימִיּוֹת דָּמָן טָעוּן כִּבּוּס, יָכוֹל אַף חַטַּאת הָעוֹף, תַּלְמוּד לוֹמַר "זֹאת". וְאָמַר "בִּמְקוֹם אֲשֶׁר תִּשָּׁחֵט הָעֹלָה תִּשָּׁחֵט הַחַטָּאת לִפְנֵי ה'" - שֶׁכָּל הַחַטָּאוֹת לֹא תְּהֵא שְׁחִיטָתָן אֶלָּא בַּצָּפוֹן (שם מח), לְפִי שֶׁלֹּא נֶאֱמַר כֵּן בְּפָרָשַׁת וַיִּקְרָא אֶלָּא בְּחַטַּאת נָשִׂיא (ד כד) וְיָחִיד (ד כט), וְכָאן נִתְרַבּוּ כֻּלָּן, חַטֹּאות הַצִּבּוּר וְחַטָּאוֹת הַפְּנִימִיּוֹת. עוֹד דָּרְשׁוּ (תורת כהנים פרשה ג ב) "קֹדֶשׁ קָדָשִׁים" - לְרַבּוֹת שַׁלְמֵי הַצִּבּוּר שֶׁלֹּא תְּהֵא שְׁחִיטָתָן אֶלָּא בַּצָּפוֹן, לְפִי שֶׁבְּכָל קָדְשֵׁי הַקֳּדָשִׁים הִטְעִין צָפוֹן. "הוּא" - פְּרָט לְתוֹדָה וְאֵיל נָזִיר. וְעוֹד נָתַן עַתָּה בְּשַׂר הַחַטָּאוֹת לִבְנֵי אַהֲרֹן (ויקרא ו':כ"ב), וְצִוָּה שֶׁיֹּאכְלוּהָ בַּחֲצַר אֹהֶל מוֹעֵד (ויקרא ו':י"ט) הַזְּכָרִים מֵהֶן וְלֹא בְּנוֹת אַהֲרֹן, וְחִדֵּשׁ דִּינִין הַרְבֵּה בַּנִּבְלָעִים מִן הַחַטָּאת (ויקרא ו':כ'-כ"א):
@20 **תְּכַבֵּס בְּמָקוֹם קָדוֹשׁ** הֶחְמִיר הַכָּתוּב בַּדָּם הַנִּבְלָע בַּבֶּגֶד לַעֲשׂוֹתוֹ כַּאֲשֶׁר הָיָה קֹדֶם הַזָּיָה שֶׁלֹּא יֵצֵא חוּץ לַקְּלָעִים. וְאָמַר "וּכְלִי חֶרֶשׂ אֲשֶׁר תְּבֻשַּׁל בּוֹ יִשָּׁבֵר" וְאַף הוּא בְּמָקוֹם קָדוֹשׁ הוּא נִשְׁבָּר וְהַחֲרָסִים נִבְלָעִין בִּמְקוֹמָם, וְאֵין עוֹשִׂין בּוֹ מְרִיקָה וּשְׁטִיפָה כְּלָל. וְכֵן הַמְּרִיקָה וְהַשְּׁטִיפָה בִּכְלִי נְחֹשֶׁת בְּמָקוֹם קָדוֹשׁ הוּא, כִּי כָל הַכְּתוּבִים נִמְשָׁכִים אֶל "מָקוֹם קָדוֹשׁ" שֶׁהִזְכִּיר:
@23 **וְכָל חַטָּאת אֲשֶׁר יוּבָא מִדָּמָהּ** שֶׁאִם הִכְנִיס מִדַּם חַטָּאת הַחִיצוֹנָה לִפְנִים פְּסוּלָה, לְשׁוֹן רַשִׁ"י (רש"י על ויקרא ו':כ"ג). וּכְפִי הַדַּעַת הַזּוֹ מַה שֶׁאָמַר "לְכַפֵּר בַּקֹּדֶשׁ" אֵינוֹ כְּמַשְׁמָעוֹ, שֶׁזּוֹ אֵינָהּ מְכַפֶּרֶת שֶׁהֲרֵי נִפְסְלָה בַּהֲבָאָה זוֹ, וּמִפְּנֵי זֶה הַפְּסוּל שֶׁלָּהּ הִיא נִשְׂרֶפֶת. אֲבָל אָמַר "לְכַפֵּר" שֶׁאִם הִכְנִיסָהּ לִפְנִים עַל דַּעַת לְכַפֵּר, שֶׁיַּזֶּה מִמֶּנָּה שָׁם כְּמַעֲשֵׂה חַטָּאת פְּנִימִית, אע"פ שֶׁלֹּא כִּפֵּר בָּהּ, כְּלוֹמַר שֶׁלֹּא הִזָּה מִדָּמָהּ כְּלוּם, נִפְסְלָה מִשְּׁעַת כְּנִיסָה וְתִשָּׂרֵף. וְאֶפְשָׁר שֶׁאִם הִכְנִיסָהּ עַל דַּעַת שֶׁלֹּא לְהַזּוֹת מִמֶּנָּה כְּלָל, שֶׁתְּהֵא כְּשֵׁרָה. וּכְדִבְרֵי ר' שִׁמְעוֹן (זבחים פב) אֵינָהּ פְּסוּלָה אֶלָּא אִם כֵּן כִּפֵּר בְּדָמָהּ, שֶׁעָשָׂה בָּהּ הַזָּאוֹת כְּמַעֲשֵׂה חַטָּאת פְּנִימִית, וּלְכָךְ אָמַר הַכָּתוּב "לְכַפֵּר", לֹא שֶׁכִּפְּרָה אֶלָּא שֶׁהוּא הֵבִיא מִדָּמָהּ לְכַפֵּר בָּהּ וְכִפֵּר כְּפִי מַחְשַׁבְתּוֹ. וּפֵרוּשׁ "לִפְנִים" שֶׁהִכְנִיס הַדָּם לַהֵיכָל. וְכֵן אִם הִכְנִיס מִדַּם פַּר כֹּהֵן מָשִׁיחַ וְהֶעְלֵם דָּבָר וּשְׂעִירֵי ע"ז לִפְנַי וְלִפְנִים, שֶׁכֻּלָּן לִפְנִים מִמְּקוֹמָן הִכְנִיסָן וּפְסוּלִין. וְאָמַר "מִדָּמָהּ" שֶׁאֲפִלּוּ מִקְצָת דָּמָהּ פּוֹסֵל, שֶׁאִם קִבֵּל דָּמָהּ בִּשְׁנֵי כּוֹסוֹת וְהִכְנִיס אֶחָד מֵהֶן לִפְנִים פְּסוּלָה (שם). וְעַל דֶּרֶךְ הַפְּשָׁט אֵין הַכָּתוּב מְדַבֵּר אֶלָּא בַּחַטָּאוֹת הַפְּנִימִיּוֹת שֶׁצִּוָּה כְּבָר בִּשְׂרֵפָתָן וּבָא כָּאן לִתֵּן לֹא תַעֲשֶׂה עַל אֲכִילָתָן, כִּי הַפָּרָשָׁה לְהַשְׁלִים דִּינֵי הַחַטָּאוֹת. וְזֶהוּ מִדְרָשׁוֹ שֶׁל רַ' יוֹסֵי הַגְּלִילִי בְּתוֹרַת כֹּהֲנִים (פרק ח ח) וּבִזְבָחִים (שם):
@31 **וְהַכֹּהֵן הַמַּקְרִיב אֶת עֹלַת אִישׁ** הַדִּין הַזֶּה נוֹהֵג בְּכָל הַקֳּדָשִׁים, וְאָמַר הַכָּתוּב עוֹלָה וְהוּא הַדִּין לְחַטָּאת וְאָשָׁם הַנִּזְכָּרִים לְמַעְלָה, וְאֵין זִבְחֵי הַשְּׁלָמִים כֵּן, וּלְכָךְ הִזְכִּיר הַכָּתוּב מִשְׁפַּט הַכֹּהֲנִים בְּאֶמְצַע הַקָּרְבָּנוֹת קֹדֶם שֶׁיְּדַבֵּר בַּשְּׁלָמִים. וּמִדְרָשׁוֹ בְּתוֹרַת כֹּהֲנִים (פרק ט ב), אֵין לִי אֶלָּא עוֹלָה, עוֹרוֹת קָדְשֵׁי קָדָשִׁים מִנַּיִן, תַּלְמוּד לוֹמַר "אֲשֶׁר הִקְרִיב", אוֹ יָכוֹל שֶׁאֲנִי מְרַבֶּה עוֹרוֹת קָדָשִׁים קַלִּים, תַּלְמוּד לוֹמַר "עוֹלָה", מַה עוֹלָה מְיֻחֶדֶת קָדְשֵׁי קָדָשִׁים יָצְאוּ קָדָשִׁים קַלִּים. וְעַל דֶּרֶךְ הַפְּשָׁט לֹא הֻצְרַךְ לוֹמַר כֵּן בְּחַטָּאת וְאָשָׁם שֶׁהֵם מַתְּנוֹת הַכְּהֻנָּה וְהַכֹּהֲנִים זוֹכִים בַּבָּשָׂר וְזוֹכִים בָּעוֹר, אֲבָל בְּעוֹלָה הֻצְרַךְ לוֹמַר שֶׁיִּזְכּוּ בָּעוֹר, וְזֶהוּ מִדְרָשׁוֹ שֶׁל רַבִּי שֶׁאָמַר, כָּל עַצְמֵנוּ לֹא הֻצְרַכְנוּ אֶלָּא לְעוֹר הָעוֹלָה שֶׁבְּכָל מָקוֹם הָעוֹר מְהַלֵּךְ אַחַר הַבָּשָׂר, בְּתוֹרַת כֹּהֲנִים (פרק ט ד) וּבִזְבָחִים (קג):
@32 **וְכָל מִנְחָה אֲשֶׁר תֵּאָפֶה בַּתַּנּוּר** דֶּרֶךְ הַפְּשָׁט יָדוּעַ בָּזֶה, שֶׁיְּצַוֶּה בְּנוֹדֵר אַחַת מִשָּׁלֹשׁ מְנָחוֹת, מַאֲפֵה תַּנּוּר וְהַמַּרְחֶשֶׁת וְהַמַּחֲבַת, שֶׁיִּהְיֶה לַכֹּהֵן הַמַּקְרִיב אוֹתָם לְבַדּוֹ, וְיֹאמַר בְּכָל שְׁאָר הַמְּנָחוֹת, כְּגוֹן הַנּוֹדֵר מִנְחָה סְתָם שֶׁהוּא מֵבִיא סֹלֶת וּבְמִנְחַת הַבִּכּוּרִים שֶׁהֵן בְּלוּלוֹת וּבְמִנְחַת חוֹטֵא וְסוֹטָה שֶׁהֵן חֲרֵבוֹת, שֶׁיְּהוּ מִתְחַלְּקוֹת לְכָל בְּנֵי אַהֲרֹן, כְּלוֹמַר לְכָל בֵּית אָב שֶׁלָּהֶם. וּפֵרוּשׁ "וְכָל מִנְחָה בְלוּלָה בַשֶּׁמֶן וַחֲרֵבָה" מִנְחָה שֶׁאֵין בָּהּ אֶלָּא סֹלֶת בְּלוּלָה אוֹ חֲרֵבָה, לֹא מֵאֵלֶּה הַנִּזְכָּרוֹת. וְיִהְיֶה טַעַם הַהֶפְרֵשׁ בֵּינֵיהֶן, מִפְּנֵי שֶׁטָּרַח הַכֹּהֵן בַּאֲפִיָּתָן וְרָאוּי לְהַרְבּוֹת שְׂכָרוֹ. אֲבָל רַבּוֹתֵינוּ (מנחות עג) לֹא רָצוּ בְּכָךְ, מִפְּנֵי שֶׁאָמַר "וְכָל מִנְחָה בְלוּלָה בַשֶּׁמֶן וַחֲרֵבָה", שֶׁכָּל הַמְּנָחוֹת שֶׁבָּעוֹלָם יִכְלֹל זֶה, שֶׁהֵם כֻּלָּם בְּלוּלוֹת אוֹ חֲרֵבוֹת, וּלְכָךְ רָאוּ שֶׁפֵּרוּשׁ "לַכֹּהֵן הַמַּקְרִיב אֹתָהּ" - לַכֹּהֲנִים הַטְּהוֹרִים הַנִּמְצָאִים שָׁם. וְכֵן מַה שֶׁאָמַר (ויקרא ז':ח') "וְהַכֹּהֵן הַמַּקְרִיב אֶת עֹלַת אִישׁ" וְ"הַכֹּהֵן אֲשֶׁר יְכַפֶּר בּוֹ לוֹ יִהְיֶה" (ויקרא ז':ז') כֻּלָּם לֹא בָּאוּ אֶלָּא לוֹמַר שֶׁלֹּא יִהְיוּ לַבְּעָלִים, אֲבָל יִהְיוּ בִּשְׂכַר הַהַקְרָבָה לַכֹּהֲנִים הַטְּהוֹרִים הַנִּמְצָאִים שָׁם, שֶׁכֻּלָּם הֵם מַקְרִיבִים בַּיָּד אוֹ בְּצִוּוּי, כִּי הַיָּחִיד מֵהֶם אוֹ הַשְּׁנַיִם וּשְׁלֹשָׁה הַמַּקְרִיבִים בִּרְשׁוּת כֻּלָּם הֵם עוֹשִׂים וּבִשְׁלִיחוּתָם, וְכֻלָּם עוֹמְדִים עַל הַקָּרְבָּן, כְּחֵלֶק הַיֹּרֵד בַּמִּלְחָמָה וּכְחֵלֶק הַיֹּשֵׁב עַל הַכֵּלִים יַחְדָּו יַחֲלֹקוּ. וְאַחַר שֶׁאָמַר שֶׁיִּהְיוּ לַכֹּהֲנִים בִּשְׂכַר עֲבוֹדָתָם חָזַר וּבֵאֵר "וְכָל מִנְחָה בְלוּלָה בַשֶּׁמֶן וַחֲרֵבָה" שֶׁהוּא כְּלַל הַמְּנָחוֹת, "לְכָל בְּנֵי אַהֲרֹן" הַמַּקְרִיבִים הַנִּזְכָּרִים, "תִּהְיֶה אִישׁ כְּאָחִיו", כְּלוֹמַר לְבֵית אָב הַטְּהוֹרִים מֵהֶם שֶׁכֻּלָּם הֵם הַמַּקְרִיבִים הַנִּזְכָּרִים. וְהִזְכִּיר הַכָּתוּב לַמְּנָחוֹת בִּשְׁמוֹתָם, מַאֲפֵה תַנּוּר וּמַרְחֶשֶׁת וּמַחֲבַת, וְאַחַר כָּךְ חָזַר וְכָלַל לוֹמַר "אִישׁ כְּאָחִיו", שֶׁלֹּא יְהֵא לָזֶה אֶלָּא מִמַּה שֶׁיֵּשׁ לָזֶה, וַאֲפִלּוּ מִנְחַת הַסֹּלֶת בָּהּ יַחְלוֹקוּ. וְאָמַר הַכָּתוּב כִּי הַדִּין הַזֶּה בַּמְּנָחוֹת וְכָל שֶׁכֵּן בִּשְׁאָר הַקָּרְבָּנוֹת שֶׁדְּמֵיהֶן מְרֻבִּין, וְהַקַּבָּלָה תַּכְרִיעַ. וְתַקָּנַת הַכֹּהֲנִים הִיא וּשְׁלוֹם הַבַּיִת. וְיִתָּכֵן שֶׁיִּהְיֶה שִׁעוּר הַכָּתוּב כְּפִי הַדַּעַת הַזּוֹ, וְכָל מִנְחָה אֲשֶׁר תֵּאָפֶה בַּתַּנּוּר וְכָל נַעֲשָׂה בַמַּרְחֶשֶׁת וְעַל מַחֲבַת לַכֹּהֵן הַמַּקְרִיב אֹתָהּ לוֹ תִהְיֶה, וְכָל מִנְחָה בְלוּלָה בַשֶּׁמֶן וַחֲרֵבָה כֵּן, וּלְכָל בְּנֵי אַהֲרֹן תִּהְיֶה אִישׁ כְּאָחִיו:
@35 **וְהִקְרִיב עַל זֶבַח הַתּוֹדָה** פֵּרְשׁוּ בּוֹ עִם זֶבַח הַתּוֹדָה, וְכֵן "עַל חַלֹּת לֶחֶם חָמֵץ" - עִמָּהֶן. וְהַנָּכוֹן שֶׁהוּא "עַל" כְּמַשְׁמָעוֹ, שֶׁיּוֹסִיף עַל הַזֶּבַח לֶחֶם, וְכֵן "עַל חַלֹּת לֶחֶם חָמֵץ יַקְרִיב קָרְבָּנוֹ" - שֶׁיָּבִיא חַלּוֹת לֶחֶם חָמֵץ וַעֲלֵיהֶם יוֹסִיף לְהָבִיא קָרְבָּנוֹ, שֶׁהוּא לֶחֶם הַמַּצָּה הַנִּזְכָּר, וְהַכֹּל יָבִיא עַל הַזֶּבַח. וְעָשָׂה עִקָּר לֶחֶם הֶחָמֵץ וּשְׁאָר הַלֶּחֶם עָלָיו, בַּעֲבוּר שֶׁהוּא מְרֻבֶּה כְּנֶגֶד כָּל שְׁאָר הַמִּינִין. וְשָׁנָה הַכָּתוּב לוֹמַר "עַל זֶבַח תּוֹדַת שְׁלָמָיו" לְמָה שֶׁדָּרְשׁוּ בּוֹ (מנחות עח), שֶׁאֵין הַלֶּחֶם קָדוֹשׁ קְדֻשַּׁת הַגּוּף עַד שֶׁיִּשָּׁחֵט הַזֶּבַח וְשֶׁיִּשָּׁחֵט עָלָיו, כְּלוֹמַר עַל מְנָת שֶׁיִּקְדַּשׁ הַלֶּחֶם עִמָּהּ. וְכָתַב רַשִׁ"י (רש"י על ויקרא ז':י"ב) "וְהִקְרִיב עַל זֶבַח הַתּוֹדָה" אַרְבַּעַת מִינֵי לֶחֶם, חַלּוֹת וּרְקִיקִים וּרְבוּכָה שְׁלֹשֶׁת מִינֵי מַצָּה, וּכְתִיב "עַל חַלֹּת לֶחֶם חָמֵץ", וְכָל מִין וָמִין עֶשֶׂר חַלּוֹת, כָּךְ מְפֹרָשׁ בִּמְנָחוֹת (עז), וְשִׁעוּרָן חָמֵשׁ סְאִין יְרוּשַׁלְמִיּוֹת שֶׁהֵן שֵׁשׁ מִדְבָּרִיּוֹת, עֶשְׂרִים עִשָּׂרוֹן. וְלֹא הִזְכִּיר הָרַב בְּעֶשְׂרִים עֶשְׂרוֹנוֹת הַלָּלוּ שֶׁמֵּהֶן עֲשָׂרָה לְחָמֵץ עִשָּׂרוֹן לְחַלָּה, וַעֲשָׂרָה לְמַצָּה שָׁלֹשׁ חַלּוֹת לְעִשָּׂרוֹן, דָּרְשׁוּ כֵן (שם עז) מִן הַכָּתוּב הַזֶּה, "עַל חַלֹּת לֶחֶם חָמֵץ" כְּנֶגֶד חָמֵץ הָבֵא מַצָּה, נִמְצְאוּ עֶשְׂרִים עִשָּׂרוֹן עֲשָׂרָה לֶחָמֵץ וַעֲשָׂרָה לַמַּצָּה, עֲשָׂרָה לְחָמֵץ עִשָּׂרוֹן לְחַלָּה, עֲשָׂרָה לְמַצָּה שָׁלֹשׁ חַלּוֹת לְעִשָּׂרוֹן, נִמְצְאוּ אַרְבָּעִים חַלּוֹת:
@37 **וְהִקְרִיב מִמֶּנּוּ אֶחָד מִכָּל קָרְבָּן** חַלָּה אַחַת שְׁלֵמָה, נִמְצָא נוֹטֵל תְּרוּמָה אַרְבַּע חַלּוֹת. וַאֲנִי תָּמֵהַּ, כְּשֶׁהוֹצִיא הַכָּתוּב מִלָּאו הַשְּׂאוֹר "קָרְבַּן רֵאשִׁית תַּקְרִיבוּ" (ויקרא ב':י"ב), לָמָּה לֹא אָמַר גַּם כֵּן "וְקָרְבַּן תּוֹדָה". וְזוֹ אֵינָהּ שְׁאֵלָה, כִּי הַכָּתוּב אָמַר "וְאֶל הַמִּזְבֵּחַ לֹא יַעֲלוּ לְרֵיחַ נִיחֹחַ", וְלֶחֶם הַתּוֹדָה אֵין מִמֶּנּוּ לַמִּזְבֵּחַ כְּלוּם, שֶׁאֵינוֹ אֶלָּא טָעוּן תְּנוּפָה. וְאע"פ שֶׁאָמְרוּ (מנחות נז) בְּלֶחֶם הַפָּנִים שֶׁעוֹבֵר עָלָיו בְּחִמּוּצוֹ, מִפְּנֵי שֶׁהַלְּבוֹנָה שֶׁעָלָיו שֶׁהִיא לַלֶּחֶם לְאַזְכָּרָה אִשֶּׁה לַה', אֲבָל לֶחֶם הַתּוֹדָה אֵין מִמֶּנּוּ לַמִּזְבֵּחַ כְּלוּם. וְאוּלַי לֹא הֻצְרַךְ הַכָּתוּב לַשִּׁיּוּר הַהוּא אֶלָּא בַּעֲבוּר הַדְּבַשׁ שֶׁלֹּא נִתְפָּרֵשׁ בַּבִּכּוּרִים שֶׁיָּבֹאוּ מִן הַדְּבַשׁ, וְכָלַל הַשְּׂאוֹר עִמּוֹ, וְאָמַר בִּשְׁנֵיהֶם "קָרְבַּן רֵאשִׁית תַּקְרִיבוּ אֹתָם", אֲבָל בַּשְּׂאוֹר הַמְפֹרָשׁ בִּמְקוֹמוֹ אֵין צֹרֶךְ לִפְרֹט אוֹתוֹ, כִּי לֹא יַתְנֶה הַכָּתוּב בִּ"מְחַלְלֶיהָ מוֹת יוּמָת" (שמות לא יד) חוּץ מֵעֲבוֹדַת הַקָּרְבָּנוֹת, וּבְ"עֶרְוַת אֵשֶׁת אָחִיךָ" (ויקרא י"ח:ט"ז) חוּץ מִן הַיְּבָמָה:
@38 **וּבְשַׂר זֶבַח תּוֹדַת שְׁלָמָיו** יֵשׁ כָּאן רִבּוּיִין הַרְבֵּה, לְרַבּוֹת חַטָּאת וְאָשָׁם וְאֵיל נָזִיר וַחֲגִיגַת אַרְבָּעָה עָשָׂר שֶׁיִּהְיוּ נֶאֱכָלִין לְיוֹם וְלַיְלָה, לְשׁוֹן רַשִׁ"י (רש"י על ויקרא ז':ט"ו). וְאֵין זֶה נָכוֹן שֶׁחֲגִיגַת אַרְבָּעָה עָשָׂר נֶאֱכֶלֶת לִשְׁנֵי יָמִים וְלַיְלָה אֶחָד כִּשְׁאָר שְׁלָמִים, וְכֵן שָׁנִינוּ בְּמַסֶּכֶת פְּסָחִים (פסחים ע"א), "אֲשֶׁר תִּזְבַּח בָּעֶרֶב בַּיּוֹם הָרִאשׁוֹן" (דברים טז ד) בַּחֲגִיגַת אַרְבָּעָה עָשָׂר הַכָּתוּב מְדַבֵּר שֶׁנֶּאֱכֶלֶת לִשְׁנֵי יָמִים וְלַיְלָה אֶחָד, שֶׁכְּשֶׁהוּא אוֹמֵר (שם) "בַּיּוֹם הָרִאשׁוֹן לַבֹּקֶר" הֲרֵי בֹּקֶר שֵׁנִי אָמוּר. וְרַשִׁ"י עַצְמוֹ כָּתַב זֶה בְּסֵדֶר רְאֵה אָנֹכִי (שם). אֲבָל בְּכָאן סָבַר הָרַב כְּדִבְרֵי בֶּן תֵּימָא (פסחים ע), דְּאָמַר חֲגִיגַת אַרְבָּעָה עָשָׂר שֶׁהִיא בָּאָה עִם הַפֶּסַח הֲרֵי הִיא כַּפֶּסַח וְנֶאֱכֶלֶת לְיוֹם וְלַיְלָה, וְאֵינָהּ נֶאֱכֶלֶת אֶלָּא צָלִי עַד חֲצוֹת וְאֵינָהּ נֶאֱכֶלֶת אֶלָּא בַּלַּיְלָה, אֲבָל לְדִבְרֵי בֶּן תֵּימָא אֵינָהּ בָּאָה בְּרִבּוּיִין הַלָּלוּ, אֶלָּא שֶׁהִיא כַּפֶּסַח לְכָל דָּבָר, וְאֵינָהּ בָּאָה אֶלָּא מִן הַצֹּאן וְזָכָר וּבֶן שָׁנָה, מִדִּכְתִיב (שמות לד כה) "וְלֹא יָלִין לַבֹּקֶר זֶבַח חַג הַפָּסַח" וְכו' כִּדְאִיתָא הָתָם. אֲבָל כָּתַב הָרַב זֶה מִבָּרַיְתָא הַשְּׁנוּיָה בְּתוֹרַת כֹּהֲנִים (פרק יב א), דְּקָתָנֵי "וּבְשַׂר זֶבַח תּוֹדַת שְׁלָמָיו בְּיוֹם קָרְבָּנוֹ יֵאָכֵל", הֲרֵי זֶה בָּא לְלַמֵּד עַל הַנֶּאֱכָלִין לְיוֹם אֶחָד שֶׁיִּהְיוּ נֶאֱכָלִין לְיוֹם אֶחָד, אֵין לִי אֶלָּא תּוֹדָה, וּמִנַּיִן לְרַבּוֹת הַלֶּחֶם, תַּלְמוּד לוֹמַר "קָרְבָּנוֹ", וּמִנַּיִן לְרַבּוֹת אֶת הַוְּלָדוֹת וְאֶת הַתְּמוּרוֹת, תַּלְמוּד לוֹמַר "וּבְשַׂר", וּמִנַּיִן לְרַבּוֹת חַטָּאוֹת וַאֲשָׁמוֹת, תַּלְמוּד לוֹמַר "זֶבַח", וּמִנַּיִן לְרַבּוֹת שַׁלְמֵי נָזִיר וּשְׁלָמִים הַבָּאִים מֵחֲמַת הַפֶּסַח, תַּלְמוּד לוֹמַר "שְׁלָמָיו", זוֹ הִיא הַבָּרַיְתָא הַזּוֹ, וּפֵרֵשׁ הָרַב בִּשְׁלָמִים הַבָּאִים מֵחֲמַת הַפֶּסַח שֶׁהִיא חֲגִיגַת אַרְבָּעָה עָשָׂר שֶׁהִיא בָּאָה עִם הַפֶּסַח. וְכֵן מָצָאתִי בְּמַסֶּכֶת פְּסָחִים בְּפֶרֶק מִי שֶׁהָיָה (צו), שֶׁפֵּרֵשׁ בִּשְׁנֵי לְשׁוֹנוֹת בִּשְׁלָמִים הַבָּאִים מֵחֲמַת הַפֶּסַח, וְכָתַב לָשׁוֹן אַחֵר חֲגִיגַת אַרְבָּעָה עָשָׂר, וְזוֹ שָׁמַעְתִּי. וְסָמַךְ הָרַב בְּכָאן עַל שְׁמוּעָתוֹ. וְאֵין הַדָּבָר כֵּן, אֶלָּא שְׁלָמִים הַבָּאִים מֵחֲמַת הַפֶּסַח הַיְנוּ מוֹתַר הַפֶּסַח, כְּגוֹן תְּמוּרָתוֹ וּפֶסַח שֶׁנִּתְכַּפְּרוּ בְּעָלָיו בְּאַחֵר, דְּכֵיוָן שֶׁמִּתְּחִלָּתוֹ אֵינוֹ נֶאֱכָל אֶלָּא לְיוֹם וָלַיְלָה אַף סוֹפוֹ כֵן, אֲבָל חֲגִיגַת אַרְבָּעָה עָשָׂר נֶאֱכֶלֶת הִיא לִשְׁנֵי יָמִים כְּדִבְרֵי חֲכָמִים. וְכֵן שָׁנִינוּ בְּתוֹרַת כֹּהֲנִים בְּאוֹתָהּ בָּרַיְתָא גוּפָהּ, דְּקָתָנֵי סוֹפָהּ (הל' ו), "וּמִמָּחֳרָת" הֲרֵי זֶה בָּא לְלַמֵּד עַל הַנֶּאֱכָלִים לִשְׁנֵי יָמִים שֶׁיִּהְיוּ נֶאֱכָלִים לִשְׁנֵי יָמִים, אֵין לִי אֶלָּא שְׁלָמִים, מִנַּיִן לְרַבּוֹת אֶת הַחֲגִיגָה שֶׁבָּאָה בִּזְמַנָּהּ וְכו', אֲרַבֶּה אֶת הַחֲגִיגָה שֶׁבָּאָה בִּזְמַנָּהּ, מִנַּיִן לַחֲגִיגָה הַבָּאָה עִם הַפֶּסַח וְכוּ':
@39 **וּמִמָּחֳרָת וְהַנּוֹתָר מִמֶּנּוּ יֵאָכֵל** וָא"ו יְתֵרָה הִיא זוֹ וְיֵשׁ כָּמוֹהוּ הַרְבֵּה בַּמִּקְרָא, כְּגוֹן "וְאֵלֶּה בְנֵי צִבְעוֹן וְאַיָּה וַעֲנָה" (בראשית לו כד), וְכֵן "תֵּת וְקֹדֶשׁ וְצָבָא מִרְמָס" (דניאל ח יג), לְשׁוֹן רַשִׁ"י (רש"י על ויקרא ז':ט"ז). וְכֵן פֵּרֵשׁ ר"א. וּלְפִי דַּעְתִּי עִנְיַן הַכָּתוּב הַזֶּה בַּעֲבוּר שֶׁאָמַר "בְּיוֹם הַקְרִיבוֹ אֶת זִבְחוֹ יֵאָכֵל וּמִמָּחֳרָת" וְהָיָה בַּמַּשְׁמָע שֶׁתְּהֵא מִצְוָה שֶׁיֵּאָכֵל בִּשְׁנֵי יָמִים, יֵאָכֵל מִקְצָתוֹ בַּיּוֹם הָרִאשׁוֹן וְיַנִּיחַ מִקְצָתוֹ לְמָחָר, וּלְפִיכָךְ חָזַר לְבָאֵר וְהַנּוֹתָר מִמֶּנּוּ בָּרִאשׁוֹן יֵאָכֵל וּמִמָּחֳרָת, לֹא שֶׁיַּשְׁאִיר מִמֶּנּוּ בְּכַוָּנָה, וְלֹא שֶׁיְּהֵא רַשַּׁאי לְהַנִּיחַ כֻּלּוֹ לְיוֹם הַמָּחֳרָת, אֲבָל מִצְוָה שֶׁיֹּאכַל מִמֶּנּוּ בָּרִאשׁוֹן וְהַנּוֹתָר בְּמִקְרֶה יֵאָכֵל בַּמָּחֳרָת הַנִּזְכָּר. וְהָעִנְיָן הַזֶּה מִדִּבְרֵי רַבּוֹתֵינוּ לְמַדְנוּהוּ, אָמְרוּ בְּתוֹרַת כֹּהֲנִים (פרק יב יא יב), "בְּיוֹם הַקְרִיבוֹ יֵאָכֵל" מִצְוָה לְהֵאָכֵל מִמֶּנּוּ יוֹם רִאשׁוֹן, יָכוֹל כֻּלּוֹ, תַּלְמוּד לוֹמַר "וּמִמָּחֳרָת", יָכוֹל מִצְוָה לְאָכְלוֹ בִּשְׁנֵי יָמִים, תַּלְמוּד לוֹמַר "וְהַנּוֹתָר", אִם הוֹתִיר הוֹתִיר, אִי "וְהַנּוֹתָר" יָכוֹל אִם הוֹתִיר כֻּלּוֹ לִשְׁנֵי יָמִים יְהֵא פָּסוּל, תַּלְמוּד לוֹמַר "יֵאָכֵל", אֲפִלּוּ כֻּלּוֹ. וְאִם תַּעֲשֶׂה הַוָּא"ו יְתֵרָה גַּם כֵּן יִתְפָּרֵשׁ וּמִמָּחֳרָת הַנּוֹתָר מִמֶּנּוּ יֵאָכֵל, לֹא שֶׁיּוֹתִיר לְדַעַת. וְלֹא יָדַעְתִּי לָמָּה הָיְתָה הַוָּא"ו בְּ"תֵת וְקֹדֶשׁ וְצָבָא מִרְמָס" יְתֵרָה אֵצֶל רַשִׁ"י, כִּי עִנְיַן הַכָּתוּב שֶׁיִּשְׁאַל עַד מָתַי תֵּת הַפֶּשַׁע שׁוֹמֵם וְעַד מָתַי קֹדֶשׁ וְצָבָא מִרְמָס:
@40 **וְהַנּוֹתָר מִבְּשַׂר הַזָּבַח בַּיּוֹם הַשְּׁלִישִׁי** אֵין עִנְיַן הַכָּתוּב שֶׁיִּהְיֶה הַנּוֹתָר לַיּוֹם הַשְּׁלִישִׁי נִשְׂרָף, וְיֵאָכֵל בַּלַּיְלָה, שֶׁכְּבָר לָמְדוּ רַבּוֹתֵינוּ (זבחים נו) מִן הַכָּתוּב בְּפָרָשַׁת קְדוֹשִׁים תִּהְיוּ (ויקרא י"ט:ו') "וְהַנּוֹתָר עַד יוֹם הַשְּׁלִישִׁי בָּאֵשׁ יִשָּׂרֵף", שֶׁכָּל מַה שֶׁיִּשָּׁאֵר מִשְּׁנֵי יָמִים כְּלָל טָעוּן שְׂרֵפָה, אֲבָל "בַּיּוֹם הַשְּׁלִישִׁי" אֵינוֹ דָּבֵק עִם "וְהַנּוֹתָר", אֲבָל הוּא דָּבוּק עִם "בָּאֵשׁ תִּשָּׂרֵף", יֹאמַר כִּי הַנּוֹתָר מִבְּשַׂר הַזֶּבַח שֶׁלֹּא נֶאֱכַל בְּיוֹם הַקְרִיבוֹ וּמִמָּחֳרָת יִשָּׂרֵף בָּאֵשׁ בַּיּוֹם הַשְּׁלִישִׁי בַּבֹּקֶר. זֶהוּ שֶׁאָמְרוּ (זבחים נה), נֶאֱכָלִים לִשְׁנֵי יָמִים וְלַיְלָה אֶחָד, כִּי בַּלַּיְלָה הַשֵּׁנִי אֵינוֹ נֶאֱכָל וְלֹא נִשְׂרָף, כִּי הִצְרִיךְ הַכָּתוּב לִשְׂרֵפַת פְּסוּלֵי הַמֻּקְדָּשִׁים הַלָּלוּ שֶׁתִּהְיֶה בַּיּוֹם כְּמוֹ שֶׁהַקְרָבַת הַכְּשֵׁרִים בַּיּוֹם:
@44 **אוֹ בִּבְהֵמָה טְמֵאָה** אָחַז הַכָּתוּב דֶּרֶךְ קְצָרָה וְהִזְכִּיר קְצָת הַטְּמֵאִים וְהוּא הַדִּין לְכֻלָּן, כִּי אַף בְּנִבְלַת בְּהֵמָה טְהוֹרָה אִם נָגַע בָּהּ וְאָכַל קֳדָשִׁים חַיָּב הַכָּרֵת הַזֶּה. וְעִנְיַן הַכְּרִיתוּת אֲבָאֵר אוֹתוֹ בְּפָרָשַׁת עֲרָיוֹת (רמב"ן על ויקרא י"ח:כ"ט) בע"ה:
@48 **כִּי כָּל אֹכֵל חֵלֶב מִן הַבְּהֵמָה אֲשֶׁר יַקְרִיב מִמֶּנָּה** לֹא יִתָּכֵן שֶׁיִּהְיֶה פֵּרוּשׁוֹ מִן הַבְּהֵמָה שֶׁהִיא עַצְמָהּ קָרְבָּן וּלְהוֹצִיא אֶת הַחֻלִּין, כִּי הַכָּתוּב כְּבָר אָסַר בְּסֵדֶר וַיִּקְרָא (ויקרא ג':י"ז) סְתָם כָּל חֵלֶב, וְאֵין שָׁם תְּנַאי וְשִׁיּוּר, וְגַם כָּאן אָסַר תְּחִלָּה כָּל חֵלֶב שׁוֹר וְכֶשֶׂב וָעֵז וְאָסַר חֵלֶב הַנְּבֵלָה וְהַטְּרֵפָה בְּאִסּוּר הַחֵלֶב (ויקרא ז':כ"ד), וְאֵינָן קָרְבָּנוֹת לַשֵּׁם. וְעוֹד שֶׁאָמַר שָׁם (ויקרא ג':י"ז) "חֻקַּת עוֹלָם לְדֹרֹתֵיכֶם בְּכֹל מוֹשְׁבֹתֵיכֶם", וְלֹא יִמָּצֵא בְּכָל עִנְיְנֵי הַקָּרְבָּנוֹת "בְּכָל מוֹשְׁבוֹתֵיכֶם", וּבְמַתְּנוֹת כְּהֻנָּה אָמַר (במדבר יח ח) "לְחָק עוֹלָם" פְּעָמִים רַבּוֹת וְלֹא הִזְכִּיר "בְּכָל מוֹשְׁבוֹתֵיכֶם", מִפְּנֵי שֶׁאֵין הַקָּרְבָּנוֹת חֻקַּת עוֹלָם בְּכָל מוֹשְׁבוֹתֵינוּ רַק בַּמִּשְׁכָּן וּבַמָּקוֹם אֲשֶׁר יִבְחַר ה'. וְאַל יְעַוֵּר עֵינֶיךָ הַמִּשְׁתַּבֵּשׁ בַּפָּסוּק "וְלֶחֶם וְקָלִי וְכַרְמֶל לֹא תֹאכְלוּ עַד עֶצֶם הַיּוֹם הַזֶּה עַד הֲבִיאֲכֶם אֶת קָרְבַּן אֱלֹהֵיכֶם חֻקַּת עוֹלָם לְדֹרֹתֵיכֶם בְּכֹל מוֹשְׁבֹתֵיכֶם" (ויקרא כ"ג:י"ד) כִּי הֶחָדָשׁ אָסוּר מִן הַתּוֹרָה בְּכָל מָקוֹם (ערלה פ"ג מ"ט), כִּי אָמַר הַכָּתוּב שֶׁלֹּא נֹאכַל לֶחֶם וְקָלִי וְכַרְמֶל לְעוֹלָם בְּכָל מוֹשְׁבוֹתֵינוּ עַד עֶצֶם הַיּוֹם שֶׁנָּבִיא הַקָּרְבָּן בְּבֵית הַבְּחִירָה, וְאִם אֵין קָרְבָּן לֹא יֵאָסֵר מִכָּאן וְאֵילָךְ, כִּי לֹא אָמַר "לֹא תֹאכְלוּ עַד הֲבִיאֲכֶם אֶת קָרְבַּן אֱלֹהֵיכֶם", אֲבָל הָאִסּוּר הוּא עַד עֶצֶם הַיּוֹם הַזֶּה בִּלְבַד, אֲבָל פֵּרוּשׁוֹ עַד עֶצֶם הַיּוֹם הַזֶּה שֶׁתָּבִיאוּ הַקָּרְבָּן כְּשֶׁתּוּכְלוּ לְהָבִיא אוֹתוֹ, וְהוּא טַעַם כְּדֵי שֶׁיִּהְיֶה הַקָּרְבָּן מִנְחָה חֲדָשָׁה. וְיִתָּכֵן שֶׁיִּהְיֶה "הַיּוֹם" נִמְשָׁךְ, עַד עֶצֶם הַיּוֹם הַזֶּה עַד יוֹם הֲבִיאֲכֶם אֶת קָרְבַּן אֱלֹהֵיכֶם. וְהָרְאָיָה הַגְּמוּרָה שֶׁפֵּרוּשׁ "מִן הַבְּהֵמָה אֲשֶׁר יַקְרִיב מִמֶּנָּה" מִן הַמִּין הַקָּרֵב, כִּי כֵן נֶאֱמַר בָּעֲרָכִין (ויקרא כ"ז:ט') "וְאִם בְּהֵמָה אֲשֶׁר יַקְרִיבוּ מִמֶּנָּה קָרְבָּן לַה' כֹּל אֲשֶׁר יִתֵּן מִמֶּנּוּ לַה' יִהְיֶה קֹּדֶשׁ", וּפֵרוּשׁוֹ בְּהֵמָה שֶׁמַּקְרִיבִין מִמִּינָהּ קָרְבָּן לַה', וְכָךְ "וְאִם כָּל בְּהֵמָה טְמֵאָה אֲשֶׁר לֹא יַקְרִיבוּ מִמֶּנָּה קָרְבָּן לַה'" (שם פסוק יא) יֹאמַר בְּפֵרוּשׁ מִן הַבְּהֵמָה הַטְּמֵאָה שֶׁאֵין מַקְרִיבִין מִמִּינָהּ, וְאֵין הֶפְרֵשׁ וְשׁוּם חִלּוּק בֵּין שֶׁמַּזְכִּיר בִּלְשׁוֹן רַבִּים "אֲשֶׁר יַקְרִיבוּ" וַ"אֲשֶׁר לֹא יַקְרִיבוּ" וּבֵין שֶׁיֹּאמַר בִּלְשׁוֹן יָחִיד "אֲשֶׁר יַקְרִיב" כִּי פֵּרוּשׁוֹ אֲשֶׁר יַקְרִיב אָדָם מִמֶּנָּה. וְכֵן אָמַר (ויקרא י"א:ל"ט) "וְכִי יָמוּת מִן הַבְּהֵמָה אֲשֶׁר הִיא לָכֶם לְאָכְלָה", הַמִּין הַנֶּאֱכָל, לֹא שֶׁהִיא עַצְמָהּ תֵּאָכֵל. וּלְפִי שֶׁאָסַר כָּל חֵלֶב מִן הַבְּהֵמָה אֲשֶׁר יָבִיא הַקָּרְבָּן מִמִּינָהּ, לֹא מִן הַמִּין שֶׁלֹּא יִתְקָרֵב, וְשֶׁמָּא יַעֲלֶה עַל הַדַּעַת לוֹמַר כִּי הַנְּבֵלָה וְהַטְּרֵפָה יֵחָשְׁבוּ כְּמִין שֶׁלֹּא יִתְקָרֵב מִמֶּנּוּ, הֻצְרַךְ לְהַזְכִּיר שֶׁיְּהֵא אָסוּר. וְזֶהוּ שֶׁנֶּאֱמַר (ויקרא ז':כ"ד) "וְאָכוֹל לֹא תֹאכְלֻהוּ", שֶׁיִּהְיוּ בְּכָרֵת כִּשְׁאָר כָּל חֵלֶב, כִּי כָל הַמִּין הַקָּרֵב יֶאֱסֹר וַאֲפִילּוּ הַנְּבֵלוֹת וְהַטְּרֵפוֹת מִמֶּנּוּ. וְאָמַר "יֵעָשֶׂה לְכָל מְלָאכָה" לוֹמַר שֶׁאֵין בּוֹ טֻמְאַת נְבֵלוֹת, כִּי יֹאמַר בַּנְּבֵלוֹת "וּבְנִבְלָתָם לֹא תִּגָּעוּ" (שם פסוק ח), וּבַחֵלֶב שֶׁלָּהֶן יֹאמַר שֶׁיִּגְּעוּ בּוֹ וְיַעֲשׂוּ מִמֶּנּוּ כָּל מְלָאכָה. וְאִם הָיָה אִסּוּר הַחֵלֶב בַּקָּרְבָּנוֹת בִּלְבַד, לָמָּה הֻצְרַךְ לוֹמַר בּוֹ "כָּל חֵלֶב לֹא תֹאכֵלוּ" שָׁם בְּפָרָשַׁת וַיִּקְרָא (ג יז), וּכְבָר צִוָּה שֶׁיַּעֲלֶה עַל הַמִּזְבֵּחַ לְרֵיחַ נִיחוֹחַ, וְאֵיךְ נֹאכַל אִשֵּׁה ה', וְלָמָּה לֹא הִזְהִיר גַּם בְּיוֹתֶרֶת הַכָּבֵד וּבִשְׁתֵּי הַכְּלָיוֹת מִן הַקָּרְבָּנוֹת, וְעוֹד לָמָּה הֻצְרַךְ לְהַזְכִּיר (ויקרא ז':כ"ג) שׁוֹר וְכֶשֶׂב וָעֵז, כִּי בְּיָדוּעַ שֶׁלֹּא יָבִיא קָרְבָּן אֶלָּא מֵהֶן. וּמִמַּה שֶׁאָמַר הַכָּתוּב בִּפְסוּלֵי הַמֻּקְדָּשִׁין (דברים טו כג) "רַק אֶת דָּמוֹ לֹא תֹאכֵל" וְלֹא הִזְכִּיר הַחֵלֶב, יַגִּיעֵנִי הַמָּקוֹם לִמְקוֹמוֹ וַאֲפָרְשֶׁנּוּ:
@53 **אֶת הַחֵלֶב עַל הֶחָזֶה** הַנִּרְאֶה מִן הַכָּתוּב הַזֶּה עַל דֶּרֶךְ פְּשָׁט שֶׁהֶחָזֶה הוּא מוּנָף עִם הַחֲלָבִים וְלֹא הַשּׁוֹק, וְהַכָּתוּב שֶׁאָמַר (ויקרא ט':כ"א) "וְאֵת הֶחָזוֹת וְאֵת שׁוֹק הַיָּמִין הֵנִיף אַהֲרֹן תְּנוּפָה" כִּי אַחֲרֵי כֵן יַחְזֹר וִינִיפֵם בִּפְנֵי עַצְמָם. וְרַבּוֹתֵינוּ אָמְרוּ (מנחות סב) שֶׁהָיָה נוֹתֵן הַחֲלָבִים עַל יַד הַבְּעָלִים וְחָזֶה וָשׁוֹק לְמַעְלָה מֵהֶן. וּלְדַעְתָּם הִזְכִּיר תְּנוּפָה בֶּחָזֶה לְבַדּוֹ לִדְרֹשׁ מַה שֶׁאָמְרוּ (תורת כהנים פרק טז ב), נִטְמְאוּ וְנִשְׁתַּיֵּר אֶחָד מֵהֶם מִנַּיִן שֶׁהוּא טָעוּן תְּנוּפָה, תַּלְמוּד לוֹמַר "חָזֶה לְהָנִיף אוֹתוֹ":
@59 **לָתֵת לָהֶם בְּיוֹם מָשְׁחוֹ אֹתָם** שִׁעוּרוֹ, אֲשֶׁר צִוָּה ה' בְּיוֹם מָשְׁחוֹ אוֹתָם לָתֵת לָהֶם מֵאֵת בְּנֵי יִשְׂרָאֵל חֻקַּת עוֹלָם. וּפֵרוּשׁ "בְּיוֹם מָשְׁחוֹ" בְּעֵת הַמְּשִׁיחָה, וְכֵן "בְּיוֹם הִקְרִיב אֹתָם לְכַהֵן" (ויקרא ז':ל"ה), בָּעֵת הַהִיא כַּאֲשֶׁר הִבְדִּילָם. וְרַבִּי אַבְרָהָם אָמַר (אבן עזרא על ויקרא ז':ל"ו) כִּי "בְּיוֹם מָשְׁחוֹ" - מִיּוֹם מָשְׁחוֹ, וְכֵן "הַנּוֹתָר בַּבָּשָׂר וּבַלָּחֶם" (ויקרא ח':ל"ב):
@61 **אֲשֶׁר צִוָּה ה' אֶת מֹשֶׁה בְּהַר סִינָי** עַל דֶּרֶךְ רַבּוֹתֵינוּ (תורת כהנים בהר פרשה א א) כִּי כָל הַמִּצְוֹת נֶאֶמְרוּ לְמֹשֶׁה בְּהַר סִינַי כְּלָלוֹתֵיהֶן וּפְרָטֵיהֶן וְדִקְדּוּקֵיהֶן, וְנִשְׁנוּ מֵהֶן בְּאֹהֶל מוֹעֵד, וְהִנֵּה מִצְוֹת וַיִּקְרָא שְׁנוּיוֹת. וְעַל דֶּרֶךְ הַפְּשָׁט שִׁעוּרוֹ אֲשֶׁר צִוָּה ה' אֶת מֹשֶׁה בְּהַר סִינָי וּבְיוֹם צַוֹּתוֹ אֶת בְּנֵי יִשְׂרָאֵל בְּמִדְבַּר סִינָי לְהַקְרִיב אֶת קָרְבְּנֵיהֶם לַה', כִּי צִוָּה בַּמִּלּוּאִים בְּהַר סִינַי וְכֵן בְּעוֹלָה וְחַטָּאת, וְצִוָּה בְּמִנְחָה וְאָשָׁם וּבְזִבְחֵי הַשְּׁלָמִים בְּמִדְבַּר סִינַי בְּאֹהֶל מוֹעֵד. וְיִתָּכֵן כִּי טַעַם "בְּהַר סִינַי" בַּמָּקוֹם הַזֶּה - לִפְנֵי הַר סִינַי, וְהוּא בְּאֹהֶל מוֹעֵד. וְכֵן "עֹלַת תָּמִיד הָעֲשֻׂיָה בְּהַר סִינַי" (במדבר כח ו), כִּי אֵינֶנּוּ בָּהָר מַמָּשׁ, כִּי עוֹלַת תָּמִיד לֹא הִתְחִילוּ בָּהּ רַק בְּאֹהֶל מוֹעֵד, דִּכְתִיב "וְזֶה אֲשֶׁר תַּעֲשֶׂה עַל הַמִּזְבֵּחַ" וְגוֹ' (שמות כט לח), וְכֵן "וַיִּסְעוּ מֵהַר ה'" (במדבר י לג), וְכֵן "רַב לָכֶם שֶׁבֶת בָּהָר הַזֶּה" (דברים א ו), וְהַטַּעַם בְּכָל אֵלֶּה כִּי יִשְׂרָאֵל חָנוּ לִפְנֵי הַר סִינַי בְּקָרוֹב לוֹ, דִּכְתִיב (שמות יט ב) "וַיִּחַן שָׁם יִשְׂרָאֵל נֶגֶד הָהָר", וְשָׁם עָמְדוּ עַד נָסְעָם מִשָּׁם לְמִדְבַּר פָּארָן, וְהִנֵּה עָשׂוּ אֹהֶל מוֹעֵד וְהֵקִימוּ אוֹתוֹ לִפְנֵי הָהָר בְּמִזְרָחוֹ, וְשָׁם הִתְחִילוּ בְּעוֹלַת הַתָּמִיד, וּבַשָּׁנָה הַשֵּׁנִית נִצְטַוּוּ עַל הַדְּגָלִים, וְהֶעֱמִידוּ הָאֹהֶל בְּתוֹךְ הַמַּחֲנוֹת בְּנָסְעָם. וּלְפִיכָךְ אָמַר הַכָּתוּב בְּכָאן כִּי זֹאת הַתּוֹרָה לָעוֹלָה וּלְכָל הַקָּרְבָּנוֹת שֶׁצִּוָּה הַשֵּׁם בְּהַר סִינָי בְּיוֹם צַוֹּתוֹ בְּמִדְבַּר סִינַי, יַגִּיד כִּי הָיָה בְּהַר סִינַי וּבְמִדְבַּר סִינַי, לְהוֹדִיעַ שֶׁלֹּא הָיְתָה בָּהָר מַמָּשׁ בִּמְקוֹם הַכָּבוֹד שֶׁשָּׁם דִּבֵּר עִמּוֹ עֲשֶׂרֶת הַדִּבְּרוֹת, וְלֹא בְּמִדְבַּר סִינַי אַחֲרֵי שֶׁנָּסְעוּ מִלִּפְנֵי הָהָר, אֲבָל הָיָה בְּמִדְבַּר סִינַי מִלִּפְנֵי הָהָר בְּתִחוּמוֹ וְקָרוֹב לוֹ, וְשָׁם אֹהֶל מוֹעֵד, כְּמוֹ שֶׁאָמַר בִּתְחִלַּת הָעִנְיָן (ויקרא א':א') "וַיִּקְרָא אֶל מֹשֶׁה וַיְדַבֵּר ה' אֵלָיו מֵאֹהֶל מוֹעֵד", הוֹדִיעַ אוֹתָנוּ עַתָּה מְקוֹם אֹהֶל מוֹעֵד:
@63 **קַח אֶת אַהֲרֹן** פָּרָשָׁה זוֹ נֶאֶמְרָה שִׁבְעַת יָמִים קֹדֶם הֲקָמַת הַמִּשְׁכָּן, שֶׁאֵין מֻקְדָּם וּמְאֻחָר בַּתּוֹרָה, לְשׁוֹן רַשִׁ"י (רש"י על ויקרא ח':ב'). וְלָמָּה נַהֲפֹךְ דִּבְרֵי אֱלֹהִים חַיִּים, וְעוֹד כִּי צִוָּה בְּפָרָשַׁת בְּיוֹם הַחֹדֶשׁ הָרִאשׁוֹן (שמות מ) בְּכָל הֲקָמַת הַמִּשְׁכָּן וּבִלְבִישַׁת אַהֲרֹן וּבָנָיו וּבִמְשִׁיחַת כֻּלָּם, וְסִפֵּר שָׁם מַעֲשֵׂה מֹשֶׁה בְּעִנְיַן הַהֲקָמָה, וְלֹא הִזְכִּיר בְּאַהֲרֹן וּבָנָיו דָּבָר עַד הַמָּקוֹם הַזֶּה, וְאֵיךְ הִפְרִישׁ עִנְיָן אֶחָד בִּשְׁתֵּי פָּרָשִׁיּוֹת וְאִחֵר הַמֻּקְדָּם. אֲבָל הַנָּכוֹן שֶׁנֹּאמַר כִּי נִצְטַוָּה בַּהֲקָמַת הַמִּשְׁכָּן בְּכ"ג בַּאֲדָר וְהֵקִים אוֹתוֹ, וְכַאֲשֶׁר עָמַד הַמִּשְׁכָּן עַל מַעֲמָדוֹ מִיָּד קָרָא לוֹ הש"י שֶׁהוּא יוֹשֵׁב הַכְּרוּבִים וְצִוָּה אוֹתוֹ עַל מַעֲשֵׂה הַקָּרְבָּנוֹת כָּל הַפָּרָשִׁיּוֹת הָאֵלֶּה שֶׁמִּתְּחִלַּת וַיִּקְרָא עַד כָּאן, כִּי רָצָה לְלַמְּדוֹ מַעֲשֵׂה כָּל הַקָּרְבָּנוֹת וּמִשְׁפְּטֵיהֶם קֹדֶם שֶׁיַּקְרִיב מֵהֶם כְּלָל, כִּי יֵשׁ בְּקָרְבְּנוֹת הַמִּלּוּאִים חַטָּאת וְעוֹלָה וּשְׁלָמִים וְלֹא יִוָּדְעוּ כָּל דִּינֵיהֶם רַק מִן הַפָּרָשִׁיּוֹת הָאֵלֶּה שֶׁהִקְדִּים לוֹ, וְאַחַר כֵּן אָמַר לוֹ "קַח אֶת אַהֲרֹן וְאֶת בָּנָיו אִתּוֹ", לְזָרֵז אוֹתוֹ בִּשְׁעַת מַעֲשֶׂה בַּמֶּה שֶׁאָמַר לוֹ מִתְּחִלָּה (שמות כט א) "וְזֶה הַדָּבָר אֲשֶׁר תַּעֲשֶׂה לָהֶם לְקַדֵּשׁ אֹתָם לְכַהֵן לִי" וְגוֹ', וְהוֹסִיף לוֹ בְּכָאן (ויקרא ח':ג') "וְאֵת כָּל הָעֵדָה הַקְהֵל אֶל פֶּתַח אֹהֶל מוֹעֵד", שֶׁיַּעֲשֶׂה בְּמַעֲמַד כֻּלָּם שֶׁיֵּדְעוּ שֶׁהש"י בָּחַר בְּאַהֲרֹן וּבְזַרְעוֹ. וְעַל דֶּרֶךְ הַיָּשָׁר נִצְטַוָּה מֹשֶׁה בִּמְלֶאכֶת הַמִּשְׁכָּן קֹדֶם לְמַעֲשֵׂה הָעֵגֶל, וּכְשֶׁנִּתְרַצָּה לוֹ הקב"ה וְהִבְטִיחוֹ שֶׁיַּשְׁרֶה שְׁכִינָתוֹ בְּתוֹכָם יָדַע מֵעַצְמוֹ שֶׁמִּצְוַת הַמִּשְׁכָּן בִּמְקוֹמָהּ עוֹמֶדֶת, וְצִוָּה לְיִשְׂרָאֵל עָלֶיהָ כְּמוֹ שֶׁפֵּרַשְׁתִּי בְּפָרָשַׁת וַיַּקְהֵל (שם לה א), וְאַחֲרֵי שֶׁהִשְׁלִימוּ הַמְּלָאכָה נֶאֱמַר לוֹ פָּרָשַׁת "בְּיוֹם הַחֹדֶשׁ הָרִאשׁוֹן בְּאֶחָד לַחֹדֶשׁ תָּקִים אֶת מִשְׁכַּן אֹהֶל מוֹעֵד" (שם מ ב), וְשָׁם נֶאֱמַר לוֹ "וְהִקְרַבְתָּ אֶת אַהֲרֹן וְאֶת בָּנָיו" וְגוֹ' (שם פסוק יב), וְהִנֵּה יָדַע שֶׁגַּם אַהֲרֹן וּבָנָיו בְּמַעֲלָתָם וּבְחִבָּתָם לִפְנֵי הַמָּקוֹם, וְעַכְשָׁו חָזַר וְזֵרְזוֹ בְּיוֹם רִאשׁוֹן שֶׁל מִלּוּאִים וּבִשְׁעַת מַעֲשֶׂה. וְהִנֵּה כָּל הַפָּרָשִׁיּוֹת כְּסִדְרָן, אֶלָּא שֶׁהִקְדִּים "וַיְכַס הֶעָנָן אֶת אֹהֶל מוֹעֵד" (שם פסוק לד) שֶׁהוּא בְּיוֹם שְׁמִינִי לַמִּלּוּאִים כְּדַעַת רַבּוֹתֵינוּ (בת"כ ריש שמיני) לְסַדֵּר כָּל עִנְיַן הֲקָמַת הַמִּשְׁכָּן, כִּי כֵן דֶּרֶךְ הַכְּתוּבִים בְּכָל מָקוֹם לְהַשְׁלִים עִנְיָן אֲשֶׁר הִתְחִיל בּוֹ:
@67 **וַיִּרְחַץ אֹתָם בַּמָּיִם** הַקָּרוֹב אֵלַי שֶׁסִּפֵּר הַכָּתוּב כִּי לְכֻלָּם רָחַץ אֲבָל לֹא הָיְתָה רְחִיצָתָם כְּאַחַת, אֲבָל רָחַץ אַהֲרֹן וְהִלְבִּישׁוֹ בְּגָדָיו וּמְשָׁחוֹ וְאַחֲרֵי כֵן רָחַץ בָּנָיו וַיַּלְבִּשֵׁם:
@68 **וַיִּתֵּן עָלָיו אֶת הַכֻּתֹּנֶת וַיַּחְגֹּר אֹתוֹ בָּאַבְנֵט** זֶה הָיָה הַסֵּדֶר שֶׁעָשָׂה בּוֹ מֹשֶׁה, אֲבָל בַּצַּוָּאָה אָמַר (שמות כט ה) "וְהִלְבַּשְׁתָּ אֶת אַהֲרֹן אֶת הַכֻּתֹּנֶת וְאֵת מְעִיל הָאֵפֹד", כִּי רָצָה לִכְלֹל אֶת הָאַבְנֵט בְּכֻלָּם בְּצַוָּאָה אַחַת, וְאָמַר (שם פסוק ט) "וְחָגַרְתָּ אֹתָם אַבְנֵט אַהֲרֹן וּבָנָיו", וְהִנֵּה הִלְבִּישׁוֹ הַכֻּתֹּנֶת עִם הָאַבְנֵט וְאַחַר כֵּן הַמְּעִיל וְהָאֵפוֹד כַּסֵּדֶר הָאָמוּר שָׁם. וְהִקְדִּים בְּכָאן "וַיַּחְגֹּר אֹתוֹ בְּחֵשֶׁב הָאֵפֹד" קֹדֶם שֶׁיָּשִׂים עָלָיו הַחֹשֶׁן, כִּי מֹשֶׁה יָדַע בְּדֶרֶךְ הַלְּבִישָׁה כִּי לְעוֹלָם תֵּכֶף לִלְבִישַׁת הַבֶּגֶד יַחְגֹּר אוֹתוֹ בַּחֲגוֹרָה הָעֲשׂוּיָה לוֹ בָּאַבְנֵט תֵּכֶף לַכֻּתֹּנֶת וּבַחֵשֶׁב תֵּכֶף לָאֵפוֹד, וְאֵין רָאוּי שֶׁתִּהְיֶה לְבִישַׁת הָאֵפוֹד בְּהַפְסָקוֹת, אֲבָל שָׁם נֶאֱמַר "וְאֶת הָאֵפֹד וְאֶת הַחֹשֶׁן וְאָפַדְתָּ לוֹ בְּחֵשֶׁב הָאֵפֹד" לְפִי שֶׁקִּצֵּר שָׁם בְּעִנְיַן הַחֹשֶׁן וְלֹא אָמַר שֶׁיִּתֵּן אוֹתוֹ בָּאֵפוֹד וְלֹא שֶׁיָּשִׂים שָׁם הָאוּרִים וְהַתֻּמִּים, שֶׁכְּבָר צִוָּה כָּל זֶה בְּמַעֲשֵׂה הָאֵפוֹד וְהַחֹשֶׁן (שם כח):
@71 **וַיִּקַּח מֹשֶׁה אֶת שֶׁמֶן הַמִּשְׁחָה וַיִּמְשַׁח אֶת הַמִּשְׁכָּן וַיִּצֹק מִשֶּׁמֶן הַמִּשְׁחָה עַל רֹאשׁ אַהֲרֹן** גַּם זֶה עָשָׂה מֹשֶׁה בְּסֵדֶר נָכוֹן, כִּי כֵן נִצְטַוָּה בְּמַעֲשֵׂה הַשֶּׁמֶן (שמות ל כו ל) "וּמָשַׁחְתָּ בוֹ אֶת אֹהֶל וְגוֹ' וְאֶת אַהֲרֹן וְאֶת בָּנָיו תִּמְשָׁח", עַל כֵּן לֹא רָצָה לִמְשֹׁחַ הַמִּשְׁכָּן עַד שֶׁהִלְבִּישׁ אַהֲרֹן וּמָשַׁח אוֹתָם כְּאֶחָד, כְּדֵי שֶׁיִּהְיֶה הַמַּקְרִיב כִּמְזֻמָּן לָבֹא אֶל הַמִּקְדָּשׁ לַעֲבֹד. וְהָיָה דַּי בְּאַהֲרֹן שֶׁהוּא קְדוֹשׁ ה', אַף עַל פִּי שֶׁכָּתוּב בְּמִצְוַת הֲקָמַת הַמִּשְׁכָּן (שם מ ט) "וּמָשַׁחְתָּ אֶת הַמִּשְׁכָּן וְאֶת כָּל אֲשֶׁר בּוֹ" וְאח"כ "וְהִקְרַבְתָּ אֶת אַהֲרֹן וְאֶת בָּנָיו וְגוֹ' וְרָחַצְתָּ אֹתָם וְהִלְבַּשְׁתָּ אֶת אַהֲרֹן" (שם פסוקים יב יג), כִּי שָׁם הִסְדִּיר כָּל הַנַּעֲשֶׂה לְאַהֲרֹן וּלְבָנָיו כְּאַחַת:
@72 **וַיַּז מִמֶּנּוּ עַל הַמִּזְבֵּחַ** כָּתַב רַשִׁ"י (רש"י על ויקרא ח':י"א) וְלֹא יָדַעְתִּי הֵיכָן נִצְטַוָּה בַּהַזָּאוֹת הַלָּלוּ. וְאֶפְשָׁר כִּי מַה שֶׁאָמַר בַּמִּזְבֵּחַ (שם פסוק י) "וְקִדַּשְׁתָּ אֶת הַמִּזְבֵּחַ וְהָיָה הַמִּזְבֵּחַ קֹדֶשׁ קָדָשִׁים", שֶׁיּוֹסִיף עָלָיו הַקִּדּוּשׁ הַזֶּה בַּהַזָּאוֹת, וְאֵינוֹ בִּמְשִׁיחָה בִּלְבַד כִּי "וְהָיָה הַמִּזְבֵּחַ קֹדֶשׁ קָדָשִׁים" שֶׁיּוֹסִיף אֵלָיו קִדּוּשׁ יוֹתֵר מִשְּׁאָר הַנִּמְשָׁחִים בַּמִּשְׁכָּן וְכָל כֵּלָיו, וְעָשָׂה לוֹ קִדּוּשׁ כַּקִּדּוּשׁ אֲשֶׁר נִצְטַוָּה לַעֲשׂוֹת בַּמַּקְרִיבִים, שֶׁאָמַר (שם כט כא) "וְהִזֵּיתָ עַל אַהֲרֹן וְעַל בְּגָדָיו", כִּי אֵין הַמִּזְבֵּחַ שֶׁהוּא כְּלִי לַקָּרְבָּנוֹת פָּחוֹת מִכְּלֵי הַמַּקְרִיבִים, וְקַל וָחֹמֶר הַדָּבָר, וְכֵן נֶאֱמַר בְּיוֹם הַכִּפּוּרִים (ויקרא ט"ז:י"ט) "וְהִזָּה עָלָיו מִן הַדָּם בְּאֶצְבָּעוֹ שֶׁבַע פְּעָמִים וְטִהֲרוֹ וְקִדְּשׁוֹ מִטֻּמְאֹת בְּנֵי יִשְׂרָאֵל", שֶׁכָּל קִדּוּשׁ הַמִּזְבֵּחַ בַּהַזָּאוֹת, וְכָל שֶׁכֵּן בַּתְּחִלָּה שֶׁצָּרִיךְ קִדּוּשׁ מִטֻּמְאָה וְזָרוּת. וְלֹא הִזְכִּיר בְּכָאן מְשִׁיחַת בָּנָיו כִּי בְּיָדוּעַ שֶׁעָשָׂה לָהֶם כַּאֲשֶׁר עָשָׂה לַאֲבִיהֶם כַּאֲשֶׁר נִצְטַוָּה (שמות מ טו) "וּמָשַׁחְתָּ אֹתָם כַּאֲשֶׁר מָשַׁחְתָּ אֶת אֲבִיהֶם", וְכָלַל זֶה בַּמֶּה שֶׁאָמַר בַּבָּנִים (ויקרא ח':י"ג) "כַּאֲשֶׁר צִוָּה ה' אֶת מֹשֶׁה". וְהַנִּרְאֶה בְּעֵינַי כִּי לֹא הָיְתָה מְשִׁיחַת הַבָּנִים בִּיצִיקַת שֶׁמֶן עַל רֹאשָׁם, כִּי לֹא נֶאֱמַר זֶה אֶלָּא בְּאַהֲרֹן, "וְיָצַקְתָּ עַל רֹאשׁוֹ וּמָשַׁחְתָּ אֹתוֹ" (שמות כט ז), וְלֹא הִזְכִּיר שָׁם מְשִׁיחַת הַבָּנִים כְּלָל, שֶׁלֹּא הָיְתָה בִּיצִיקָה כָּמוֹהוּ. וְיִתָּכֵן שֶׁלֹּא הָיְתָה בַּבָּנִים מְשִׁיחָה זוּלָתִי הַהַזָּאוֹת שֶׁהִזָּה מִשֶּׁמֶן הַמִּשְׁחָה עַל בָּנָיו וְעַל בִּגְדֵיהֶם, וְכֵן תִּרְאֶה בְּפָרָשַׁת "וְזֶה הַדָּבָר אֲשֶׁר תַּעֲשֶׂה לָהֶם לְקַדֵּשׁ אֹתָם" (שם פסוק א), שֶׁצִּוָּה לִמְשֹׁחַ הָאָב "וְלָקַחְתָּ אֶת שֶׁמֶן הַמִּשְׁחָה וְיָצַקְתָּ עַל רֹאשׁוֹ", וְלֹא צִוָּה לִמְשֹׁחַ הַבָּנִים כְּלָל לֹא בִּיצִיקָה וְלֹא בִּמְשִׁיחָה, אֲבָל בְּפָרָשַׁת הֲקָמַת הַמִּשְׁכָּן (שם מ טו) אוֹמֵר "וּמָשַׁחְתָּ אֹתָם כַּאֲשֶׁר מָשַׁחְתָּ אֶת אֲבִיהֶם", שֶׁלֹּא הִזְכִּיר שָׁם הַזָּאוֹת כְּלָל, וְכֵן בְּפָרָשַׁת הַשֶּׁמֶן (שם ל ל), וְלֹא הֻזְכְּרוּ מְשִׁיחָה וְהַזָּאוֹת בַּבָּנִים בְּמָקוֹם אֶחָד. לְכָךְ אֲנִי אוֹמֵר שֶׁלֹּא עָשָׂה בָּהֶם אֶלָּא אַחַת מֵהֶן, וְהֵן הַהַזָּאוֹת:
@76 **וַיְחַטֵּא אֶת הַמִּזְבֵּחַ** חִטְּאוֹ וְטִהֲרוֹ מִזָּרוּת לִכָּנֵס בִּקְדֻשָּׁה. **וַיְקַדְּשֵׁהוּ** בַּעֲבוֹדָה זוֹ, **לְכַפֵּר עָלָיו** מֵעַתָּה כָּל הַכַּפָּרוֹת, לְשׁוֹן רַשִׁ"י (רש"י על ויקרא ח':ט"ו). וְאִם כֵּן הַכָּתוּב יְסַפֵּר כִּי בָּזֶה נִתְקַדֵּשׁ וְרָאוּי לְכַפֵּר עָלָיו מִכָּאן וְאֵילָךְ, וְזֶה כָּעִנְיָן שֶׁנֶּאֱמַר בִּיחֶזְקֵאל (מג כו כז) "שִׁבְעַת יָמִים יְכַפְּרוּ אֶת הַמִּזְבֵּחַ וְטִהֲרוּ אֹתוֹ וּמִלְאוּ אֶת יָדָיו וִיכַלּוּ אֶת הַיָּמִים וְהָיָה בַיּוֹם הַשְּׁמִינִי וָהָלְאָה יַעֲשׂוּ הַכֹּהֲנִים עַל הַמִּזְבֵּחַ אֶת עוֹלוֹתֵיכֶם וְאֶת שַׁלְמֵיכֶם וְרָצִיתִי אֶתְכֶם נְאֻם ה'", וִילַמֵּד בְּכָאן כִּי בַּדָּם נַעֲשָׂה זֶה, וְאֵין הַקְטָרַת הָאֵמוּרִים מְעַכֶּבֶת בְּחִנּוּךְ הַמִּזְבֵּחַ, שֶׁכֵּן לְדוֹרוֹת אֵינָהּ מְעַכֶּבֶת בַּכַּפָּרָה. אֲבָל בַּתּוֹסֶפְתָּא שֶׁל פָּרָשַׁת מִלּוּאִים (תורת כהנים צו מלואים טו) רָאִיתִי, כַּפָּרָה זוֹ אֵינִי יוֹדֵעַ מַה הִיא, מִנַּיִן אַתָּה אוֹמֵר שֶׁלֹּא הָיְתָה כַּפָּרָה זוֹ אֶלָּא שֶׁאָמַר מֹשֶׁה, בְּשָׁעָה שֶׁיָּצָא הַכָּרוֹז לְהִתְנַדֵּב בַּמִּקְדָּשׁ דָּחֲקוּ יִשְׂרָאֵל אִישׁ וְאִשָּׁה וְהֵבִיאוּ שֶׁלֹּא בְּטוֹבָתָן, תְּהֵא כַּפָּרָה זוֹ שֶׁלֹּא יִתְנַדְּבוּ דָּבָר גָּזוּל לַמִּקְדָּשׁ, וְכֵן הוּא אוֹמֵר (ישעיהו סא ח) "כִּי אֲנִי ה' אֹהֵב מִשְׁפָּט שֹׂנֵא גָזֵל בְּעוֹלָה". וּכְבָר הִזְכִּיר רַשִׁ"י גַּם זֶה בְּפָרָשַׁת וְאַתָּה תְּצַוֶּה (שמות כט לו):
@78 **וְאֶת הַפָּר וְאֶת עֹרוֹ וְאֶת בְּשָׂרוֹ וְאֶת פִּרְשׁוֹ** יִכְלֹל בַּפָּר הַקָּרֵב שֶׁאֵינוֹ בִּכְלַל בְּשָׂרוֹ עֲצָמוֹת וְגִידִים וְקַרְנַיִם וּטְלָפַיִם שֶׁהֵם מִלְּבַד עוֹרוֹ וּבְשָׂרוֹ וּפִרְשׁוֹ, אוֹ יִהְיֶה הַוָּא"ו מִן הַמְשַׁמְּשִׁין בְּיָתֵר, וְהוּא כְּמוֹ "וְשָׂרַף אֶת הַפָּרָה לְעֵינָיו אֶת עֹרָהּ וְאֶת בְּשָׂרָהּ וְאֶת דָּמָהּ עַל פִּרְשָׁהּ יִשְׂרֹף" (במדבר יט ה):
@81 **וְאֶת הָאַיִל נִתַּח לִנְתָחָיו** אֵין נִתּוּחַ אֶלָּא לְאַחַר הֶפְשֵׁט, אֲבָל קִצֵּר בַּהַפְשָׁטָה בְּכָאן שֶׁכְּבָר צִוָּה בָּזֶה בְּפָרָשַׁת הָעוֹלָה (ויקרא א':ו'), וְאָמַר "וַיַּקְטֵר מֹשֶׁה אֶת הָרֹאשׁ וְאֶת הַנְּתָחִים" בִּזְמַן הַהַקְטָרָה, וְהוּא אַחַר "וְאֶת הַקֶּרֶב וְאֶת הַכְּרָעַיִם רָחַץ בַּמָּיִם", וְזֶהוּ שֶׁאָמַר "וַיַּקְטֵר מֹשֶׁה אֶת כָּל הָאַיִל" כִּי הַכֹּל הִקְטִיר כְּאַחַת אַחַר הָרְחִיצָה, אֶלָּא שֶׁהִפְרִידָם לְלַמֵּד שֶׁאֵין הַנְּתָחִים טְעוּנִין רְחִיצָה:
@83 **וַיַּקְרֵב אֶת הָאַיִל הַשֵּׁנִי אֵיל הַמִּלֻּאִים** כְּבָר פֵּרַשְׁתִּי (שמות כח מא) כִּי עִנְיַן הַמִּלּוּאִים שֶׁתִּהְיֶה לָהֶם יָד שְׁלֵמָה לַעֲבֹד אֶת עֲבֹדַת ה', וְיֹאמַר כֵּן בַּמִּזְבֵּחַ עַצְמוֹ וְהָעוֹבְדִים. וְהִנֵּה כָּל הַקָּרְבָּנוֹת הָאֵלּוּ בָּאִים לְמַלֵּא אֶת יָדָם, כְּדִכְתִיב (שם כט א) "וְזֶה הַדָּבָר אֲשֶׁר תַּעֲשֶׂה לָהֶם לְקַדֵּשׁ אֹתָם לְכַהֵן לִי לְקַח פַּר אֶחָד בֶּן בָּקָר וְאֵילִם שְׁנַיִם תְּמִימִם", אֲבָל נִקְרָא הָאַיִל הַשֵּׁנִי "אֵיל הַמִּלּוּאִים" בַּעֲבוּר שֶׁהוּא סוֹף הַקָּרְבָּנוֹת הַלָּלוּ, וּבוֹ תִּמָּלֵא יָדָם וְכִהֲנוּ לְפָנָיו ית', לְפָרֵשׁ כִּי כֻלָּם מְעַכְּבִין בָּעִנְיָן. וְיִתָּכֵן כִּי הַחַטָּאת לְכַפֵּר עַל הַמִּזְבֵּחַ וּלְקַדְּשׁוֹ, כִּי כֵן כְּתִיב (ויקרא ח':ט"ו), וְהָעוֹלָה לְהַרְצָאָה עַל הַכֹּהֲנִים, כְּכַפָּרַת כָּל עוֹלַת נְדָבָה, וְהַשְּׁלָמִים תּוֹדָה לַשֵּׁם שֶׁנָּתַן לָהֶם בְּבֵיתוֹ וּבְחוֹמוֹתָיו יָד וָשֵׁם. וְהִנֵּה הַשְּׁלָמִים לְבַדָּם בָּאִים עַל מִלּוּי הַיָּדַיִם, וּלְכָךְ יִקָּרְאוּ מִלּוּאִים. וְיֹאמַר "מִלּוּאִים" וְלֹא מִלּוּי, בַּעֲבוּר כִּי הַחֲלָבִים וְהַשּׁוֹק גַּם תְּרוּמַת הַלֶּחֶם הַכֹּל קָרֵב:
@91 **וַיִּקַּח מֹשֶׁה מִשֶּׁמֶן הַמִּשְׁחָה וּמִן הַדָּם אֲשֶׁר עַל הַמִּזְבֵּחַ** לֹא יָדַעְתִּי אִם מְעָרְבָן לַהַזָּאוֹת הַלָּלוּ, כְּמוֹ "וְלָקַח מִדַּם הַפָּר וּמִדַּם הַשָּׂעִיר וְנָתַן עַל קַרְנוֹת הַמִּזְבֵּחַ" (ויקרא ט"ז:י"ח). וְכֵן לֹא נִתְבָּרֵר לִי מָה טַעַם אִחֵר הַזָּאוֹת הַלָּלוּ לְאַחַר הַקְטָרָה שֶׁל מִלּוּאִים, כִּי בַּצַּוָּאָה (שמות כט כא) הִקְדִּים הַהַזָּאוֹת וְאח"כ אָמַר "וְלָקַחְתָּ מִן הָאַיִל הַחֵלֶב וְהָאַלְיָה" (שם פסוק כב). וְאוּלַי בַּעֲבוּר שֶׁאָמַר שָׁם (ויקרא ח':כ"א) "וְקָדַשׁ הוּא וּבְגָדָיו וּבָנָיו וּבִגְדֵי בָנָיו אִתּוֹ" לָמַד מֹשֶׁה כִּי הוּא הַדָּבָר הַמְאֻחָר הַנַּעֲשֶׂה בָּהֶם שֶׁבּוֹ יִהְיוּ קְדוֹשִׁים לְגַמְרֵי, כִּי לֹא הִזְכִּיר שָׁם בַּמְּשִׁיחָה (שם ז) קִדּוּשׁ וְלֹא בְּמַתַּן בְּהוֹנוֹת (שם כ), וְכָאן אָמַר "וַיִּמְשַׁח אוֹתוֹ לְקַדְּשׁוֹ" (ויקרא ח':י"ב), לֹא שֶׁיִּקְדַּשׁ לְגַמְרֵי, עַד שֶׁעָשָׂה הַהַזָּאוֹת וְאָמַר בָּהֶן (כאן) "וַיְקַדֵּשׁ אֶת אַהֲרֹן וְאֶת בָּנָיו". וְהִנֵּה הִשְׁלִים קְדֻשַּׁת הָאָב וְהַבָּנִים כְּאַחַת בַּהַזָּאוֹת הַלָּלוּ. וְכָךְ אָמְרוּ בְּת"כ (צו מלואים לד) "וַיְקַדֵּשׁ אֶת אַהֲרֹן", הָא לָמַדְתָּ שֶׁלֹּא שָׁלַם קִדּוּשׁ אַהֲרֹן וְהַבָּנִים אֶלָּא בְּהַזָּאַת דָּם:
@93 **וְהַנּוֹתָר בַּבָּשָׂר וּבַלָּחֶם** הַבֵּי"ת בִּשְׁתֵּי הַמִּלּוֹת תְּשַׁמֵּשׁ כְּמוֹ מֵ"ם, וְהַנּוֹתָר מִן הַבָּשָׂר וּמִן הַלֶּחֶם, וְכֵן "בַיּוֹם הַשְּׁמִינִי וָהָלְאָה" (יחזקאל מג כז), "בַּשָּׁנָה הַהִיא שְׁמֹנֶה עֶשְׂרֵה שָׁנָה" (שופטים י ח). וְלֹא פֵּרֵשׁ הַכָּתוּב "וְהַנּוֹתָר עַד הַבֹּקֶר" כִּי כְּבָר לָמְדוּ מִשְׁפַּט הַקָּרְבָּנוֹת וְיָדְעוּ שֶׁשְּׁלָמִים הַלָּלוּ נִדּוֹנִין כַּחֲמוּרִין שֶׁבָּהֶן שֶׁנֶּאֱכָלִין לְיוֹם וְלַיְלָה, אוֹ שֶׁקִּצֵּר הַכָּתוּב כָּאן בַּעֲבוּר שֶׁהוּא מְפֹרָשׁ בַּצַּוָּאָה (שמות כט לד) "וְאִם יִוָּתֵר מִבְּשַׂר הַמִּלֻּאִים וּמִן הַלֶּחֶם עַד הַבֹּקֶר":
@96 **וּפֶתַח אֹהֶל מוֹעֵד תֵּשְׁבוּ יוֹמָם וָלַיְלָה שִׁבְעַת יָמִים וּשְׁמַרְתֶּם אֶת מִשְׁמֶרֶת ה' וְלֹא תָמוּתוּ** עַל דַּעַת הַבָּרַיְתָא שֶׁל תּוֹרַת כֹּהֲנִים (שמיני מלואים מב) עִנְיַן הַפָּסוּק הַזֶּה שֶׁלֹּא יֵצְאוּ מִפֶּתַח אֹהֶל מוֹעֵד יוֹמָם וָלַיְלָה בִּשְׁעַת עֲבוֹדָה, כְּלוֹמַר עַד שֶׁיַּשְׁלִימוּ כָּל הָעֲבוֹדָה הַמֻּטֶּלֶת עֲלֵיהֶם בְּאוֹתוֹ הָעֵת, וְהִיא מִצְוָה נוֹהֶגֶת לְדוֹרוֹת שֶׁלֹּא יַנִּיחַ כֹּהֵן עֲבוֹדָה וְיֵצֵא וְחַיָּבִין עָלֶיהָ מִיתָה, וְהוּא שֶׁאָמַר בְּכֹהֵן גָּדוֹל (ויקרא כ"א:י"ב) "וּמִן הַמִּקְדָּשׁ לֹא יֵצֵא וְלֹא יְחַלֵּל", אָמְרוּ (בת"כ כאן), אֵימָתַי אֵינוֹ יוֹצֵא וְאֵינוֹ מְחַלֵּל, הֱוֵי אוֹמֵר בִּשְׁעַת עֲבוֹדָה. וְדָרְשׁוּ (שם), "פֶּן תָּמוּתוּ" (ויקרא י':ז'), מִמַּשְׁמַע לָאו אַתָּה שׁוֹמֵעַ הֵן, אֵין לִי אֶלָּא אַהֲרֹן וּבָנָיו שֶׁנִּמְשְׁחוּ בְּשֶׁמֶן הַמִּשְׁחָה שֶׁאִם יָצְאוּ בִּשְׁעַת עֲבוֹדָה חַיָּבִין מִיתָה, מִנַּיִן לְכָל הַכֹּהֲנִים שֶׁבְּכָל הַדּוֹרוֹת, תַּלְמוּד לוֹמַר "כִּי שֶׁמֶן מִשְׁחַת ה' עֲלֵיכֶם" (שם), פֵּרוּשׁ, שֶׁלֹּא אָמַר כִּי בְּשֶׁמֶן מִשְׁחַת ה' אַתֶּם מְשֻׁחִים, וְאָמַר "עֲלֵיכֶם" כְּמוֹ "וְהָיְתָה לִהְיֹת לָהֶם מָשְׁחָתָם לִכְהֻנַּת עוֹלָם לְדֹרֹתָם" (שמות מ טו):
@97 **וַיַּעַשׂ אַהֲרֹן וּבָנָיו אֵת כָּל הַדְּבָרִים אֲשֶׁר צִוָּה ה' בְּיַד מֹשֶׁה** יֹאמַר בְּכָל מָקוֹם "כַּאֲשֶׁר צִוָּה ה' בְּיַד מֹשֶׁה" אֲבָל בְּכָאן מִפְּנֵי שֶׁהוֹסִיפוּ עַל הַמִּצְוָה לֹא אָמַר כֵּן, כִּי לֹא עָשׂוּ כַּאֲשֶׁר צִוָּה ה' אֶת מֹשֶׁה, אֲבָל עָשׂוּ כָּל הַדְּבָרִים אֲשֶׁר צִוָּה ה', וְעוֹד נוֹסַף עֲלֵיהֶם מַה שֶׁאָמַר בְּאֵשׁ זָרָה "אֲשֶׁר לֹא צִוָּה אֹתָם" (ויקרא י':א'):
